//! GF(2^16) arithmetic for PAR2 Reed-Solomon repair.
//!
//! The PAR2 field: GF(65536) generated by x^16 + x^12 + x^3 + x + 1
//! (0x1100B), with 2 as the primitive element - the same field
//! par2cmdline uses, so recovery data interoperates bit-for-bit.
//!
//! Everything routes through one pair of log/exp tables (built once,
//! 512 KB). Buffer-scale work - "dst ^= c · src over u16 words" - uses
//! the classic split-table trick: a 256-entry table for each byte half
//! of the word turns a full GF multiply into two lookups and an XOR.

use std::sync::OnceLock;

/// The PAR2 generator polynomial (bit 16 implied).
const POLY: u32 = 0x1100B;
/// Order of the multiplicative group (2^16 − 1).
pub const ORDER: u32 = 65535;

struct Tables {
    /// exp[i] = 2^i; doubled to 2·ORDER entries so `log a + log b` and
    /// `ORDER − log a` index without a modulo.
    exp: Vec<u16>,
    /// log[a] = i with 2^i = a, for a ≠ 0. log[0] is unused (0 has no log).
    log: Vec<u16>,
}

fn tables() -> &'static Tables {
    static TABLES: OnceLock<Tables> = OnceLock::new();
    TABLES.get_or_init(|| {
        let mut exp = vec![0u16; ORDER as usize * 2];
        let mut log = vec![0u16; 65536];
        let mut v: u32 = 1;
        for i in 0..ORDER as usize {
            exp[i] = v as u16;
            log[v as usize] = i as u16;
            v <<= 1;
            if v & 0x1_0000 != 0 {
                v ^= POLY;
            }
        }
        debug_assert_eq!(v, 1, "2 must have full order {ORDER}");
        for i in 0..ORDER as usize {
            exp[ORDER as usize + i] = exp[i];
        }
        Tables { exp, log }
    })
}

pub fn mul(a: u16, b: u16) -> u16 {
    if a == 0 || b == 0 {
        return 0;
    }
    let t = tables();
    t.exp[t.log[a as usize] as usize + t.log[b as usize] as usize]
}

/// 2^e with e reduced mod ORDER - every PAR2 RS matrix entry is one of
/// these: input slice i's base is 2^{k_i}, so base^exponent = 2^{k_i·e}.
pub fn pow2(e: u64) -> u16 {
    tables().exp[(e % ORDER as u64) as usize]
}

/// Multiplicative inverse. `a` must be non-zero.
pub fn inv(a: u16) -> u16 {
    debug_assert_ne!(a, 0, "0 has no inverse");
    let t = tables();
    t.exp[(ORDER - t.log[a as usize] as u32) as usize]
}

/// Split-multiply table for one scalar `c`: word × c via two byte lookups
/// (scalar), plus 4-bit nibble tables for the SIMD fold paths (NEON on
/// aarch64, SSSE3/AVX2 on x86_64).
pub struct MulTable {
    lo: [u16; 256],
    hi: [u16; 256],
    /// SIMD nibble tables: `nl[j][n]`/`nh[j][n]` are the low/high byte of
    /// `c · (n << 4j)` for nibble `n` - a u16 word's product is the XOR of
    /// its four nibbles' contributions, each a single 16-byte table shuffle
    /// (`vqtbl1q_u8` on NEON, `pshufb` on x86).
    #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
    nl: [[u8; 16]; 4],
    #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
    nh: [[u8; 16]; 4],
    /// GFNI 8x8 bit-matrices `[ll, hl, lh, hh]`: multiply-by-c over
    /// GF(2^16) is GF(2)-linear, so it splits into four byte→byte maps
    /// (product low/high byte from source low/high byte), each one
    /// `gf2p8affineqb` - the whole word product costs 4 affines where
    /// the nibble path needs 8 shuffles plus the nibble extraction.
    #[cfg(target_arch = "x86_64")]
    affine: [u64; 4],
}

/// Pack the byte→byte GF(2) linear map `j → take(products[j])` into the
/// `gf2p8affineqb` matrix operand: destination bit `i`'s row lives in
/// qword byte `7 − i`, and bit `j` of a row selects source bit `j`.
#[cfg(target_arch = "x86_64")]
fn affine_matrix(products: &[u16; 8], take: fn(u16) -> u8) -> u64 {
    let mut m = 0u64;
    for i in 0..8 {
        let mut row = 0u8;
        for (j, &p) in products.iter().enumerate() {
            row |= ((take(p) >> i) & 1) << j;
        }
        m |= (row as u64) << (8 * (7 - i));
    }
    m
}

/// The SIMD nibble tables for multiply-by-`c` (see [`MulTable::nl`]).
///
/// Built from the field's linearity rather than 64 multiplies: the
/// products of `c` by the sixteen powers of two come off one `xtime`
/// chain (shift, reduce by 0x1100B), and every table entry is the XOR
/// of the powers its nibble has set, filled by the subset walk. Some
/// 16 shifts and 60 XORs where the old form was 64 log/antilog
/// multiplies - and the multi-source fold kernels build four of these
/// per (row, group, tile) call, which at the 4 KiB tiles a heavy repair
/// tiles down to was a measurable share of the call (2 Sep 2026,
/// i5-10600KF). Pinned to the multiply by `nibble_tables_match_mul`.
#[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
fn nibble_tables(c: u16) -> ([[u8; 16]; 4], [[u8; 16]; 4]) {
    // pw[k] = c · x^k in GF(2^16) for k in 0..16.
    let mut pw = [0u16; 16];
    let mut v = c;
    for slot in pw.iter_mut() {
        *slot = v;
        let carry = v & 0x8000 != 0;
        v <<= 1;
        if carry {
            v ^= 0x100B;
        }
    }
    let mut nl = [[0u8; 16]; 4];
    let mut nh = [[0u8; 16]; 4];
    for (j, (nlj, nhj)) in nl.iter_mut().zip(nh.iter_mut()).enumerate() {
        let mut t = [0u16; 16];
        for b in 0..4 {
            let basis = pw[4 * j + b];
            for i in 0..(1usize << b) {
                t[i | (1 << b)] = t[i] ^ basis;
            }
        }
        for n in 0..16 {
            nlj[n] = t[n] as u8;
            nhj[n] = (t[n] >> 8) as u8;
        }
    }
    (nl, nh)
}

impl MulTable {
    pub fn new(c: u16) -> MulTable {
        let mut lo = [0u16; 256];
        let mut hi = [0u16; 256];
        for b in 0..256u16 {
            lo[b as usize] = mul(c, b);
            hi[b as usize] = mul(c, b << 8);
        }
        #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
        let (nl, nh) = nibble_tables(c);
        #[cfg(target_arch = "x86_64")]
        let affine = affine_matrices(c);
        MulTable {
            lo,
            hi,
            #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
            nl,
            #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
            nh,
            #[cfg(target_arch = "x86_64")]
            affine,
        }
    }

    #[inline]
    pub fn mul(&self, w: u16) -> u16 {
        self.lo[(w & 0xff) as usize] ^ self.hi[(w >> 8) as usize]
    }

    /// dst ^= c · src, with `src` raw little-endian bytes and `dst` u16
    /// words. `src` may be shorter than `dst` - PAR2 zero-pads tail
    /// slices, and c·0 contributes nothing, so short input just stops
    /// early. An odd trailing byte is the low half of a final word.
    ///
    /// This is the PAR2 repair fold hotspot (one call per syndrome-row ×
    /// present-slice, over whole blocks). On aarch64 the bulk runs on
    /// NEON - 16 words per iteration via nibble-table `vqtbl` lookups -
    /// and on x86_64 on AVX2 (32 words/iter) or SSSE3 (16), picked at
    /// runtime; the scalar path (below) handles the short tail.
    pub fn xor_mul_into(&self, dst: &mut [u16], src: &[u8]) {
        assert!(src.len().div_ceil(2) <= dst.len(), "src longer than dst");
        #[cfg(target_arch = "aarch64")]
        let done = fold_simd(&self.nl, &self.nh, dst, src);
        #[cfg(target_arch = "x86_64")]
        let done = fold_simd(&self.nl, &self.nh, &self.affine, dst, src);
        #[cfg(not(any(target_arch = "aarch64", target_arch = "x86_64")))]
        let done = 0usize;
        Self::xor_mul_scalar(&self.lo, &self.hi, &mut dst[done..], &src[done * 2..]);
    }

    /// Scalar fold (the whole op off aarch64; the tail on it). Also the
    /// differential oracle for the NEON path.
    fn xor_mul_scalar(lo: &[u16; 256], hi: &[u16; 256], dst: &mut [u16], src: &[u8]) {
        let words = src.len() / 2;
        for (d, s) in dst.iter_mut().zip(src.as_chunks::<2>().0) {
            *d ^= lo[s[0] as usize] ^ hi[s[1] as usize];
        }
        if src.len() % 2 == 1 {
            dst[words] ^= lo[src[src.len() - 1] as usize];
        }
    }
}

/// The runtime-dispatched SIMD fold over explicit tables, shared by
/// [`MulTable`] and [`FoldTable`]: bulk-folds whole chunks and returns
/// the number of u16 WORDS processed; the caller finishes the tail from
/// whatever scalar tables it carries.
#[cfg(target_arch = "aarch64")]
#[inline]
fn fold_simd(nl: &[[u8; 16]; 4], nh: &[[u8; 16]; 4], dst: &mut [u16], src: &[u8]) -> usize {
    // SAFETY: NEON is baseline on aarch64, so no runtime feature check
    // is needed (see fold_neon's docs); every caller asserts dst has a
    // word for every byte pair of src.
    unsafe { fold_neon(nl, nh, dst, src) }
}

/// See the aarch64 twin above. Pre-SSSE3 parts fold nothing here and
/// run entirely on the caller's scalar tail.
#[cfg(target_arch = "x86_64")]
#[inline]
fn fold_simd(
    nl: &[[u8; 16]; 4],
    nh: &[[u8; 16]; 4],
    affine: &[u64; 4],
    dst: &mut [u16],
    src: &[u8],
) -> usize {
    if is_x86_feature_detected!("gfni") && is_x86_feature_detected!("avx2") {
        // SAFETY: GFNI and AVX2 verified by the detects on this branch;
        // every caller asserts dst has a word for every byte pair of src.
        unsafe { fold_gfni(affine, dst, src) }
    } else if is_x86_feature_detected!("avx2") {
        // SAFETY: AVX2 verified by the detect on this branch; dst covers
        // src per the caller's assert.
        unsafe { fold_avx2(nl, nh, dst, src) }
    } else if is_x86_feature_detected!("ssse3") {
        // SAFETY: SSSE3 verified by the detect on this branch; dst covers
        // src per the caller's assert.
        unsafe { fold_ssse3(nl, nh, dst, src) }
    } else {
        0
    }
}

/// NEON fold: `dst[i] ^= c · src_word[i]` for whole 32-byte (16-word)
/// chunks. Returns the number of u16 WORDS processed; the caller runs
/// the remainder scalar. NEON is baseline on aarch64, so no runtime
/// feature check is needed.
#[cfg(target_arch = "aarch64")]
unsafe fn fold_neon(nl: &[[u8; 16]; 4], nh: &[[u8; 16]; 4], dst: &mut [u16], src: &[u8]) -> usize {
    use std::arch::aarch64::*;
    let chunks = src.len() / 32;
    if chunks == 0 {
        return 0;
    }
    // SAFETY: NEON intrinsics are baseline on aarch64 (no feature
    // precondition). All pointer accesses stay within the first
    // chunks * 32 bytes: in bounds for src by chunks = src.len() / 32,
    // and for dst by the caller's guarantee that dst has a word for
    // every byte pair of src (the assert in xor_mul_into).
    unsafe {
        let (t0l, t1l, t2l, t3l) = (
            vld1q_u8(nl[0].as_ptr()),
            vld1q_u8(nl[1].as_ptr()),
            vld1q_u8(nl[2].as_ptr()),
            vld1q_u8(nl[3].as_ptr()),
        );
        let (t0h, t1h, t2h, t3h) = (
            vld1q_u8(nh[0].as_ptr()),
            vld1q_u8(nh[1].as_ptr()),
            vld1q_u8(nh[2].as_ptr()),
            vld1q_u8(nh[3].as_ptr()),
        );
        let mask = vdupq_n_u8(0x0f);
        let dst_bytes = dst.as_mut_ptr() as *mut u8;
        for c in 0..chunks {
            // src bytes deinterleave to low/high bytes of the 16 words.
            let s = vld2q_u8(src.as_ptr().add(c * 32));
            let n0 = vandq_u8(s.0, mask);
            let n1 = vshrq_n_u8::<4>(s.0);
            let n2 = vandq_u8(s.1, mask);
            let n3 = vshrq_n_u8::<4>(s.1);
            let plo = veorq_u8(
                veorq_u8(vqtbl1q_u8(t0l, n0), vqtbl1q_u8(t1l, n1)),
                veorq_u8(vqtbl1q_u8(t2l, n2), vqtbl1q_u8(t3l, n3)),
            );
            let phi = veorq_u8(
                veorq_u8(vqtbl1q_u8(t0h, n0), vqtbl1q_u8(t1h, n1)),
                veorq_u8(vqtbl1q_u8(t2h, n2), vqtbl1q_u8(t3h, n3)),
            );
            let dp = dst_bytes.add(c * 32);
            let d = vld2q_u8(dp);
            vst2q_u8(dp, uint8x16x2_t(veorq_u8(d.0, plo), veorq_u8(d.1, phi)));
        }
    }
    chunks * 16
}

/// SSSE3 fold: the `pshufb` twin of the NEON path - same nibble
/// tables, 16 words per 32-byte chunk. x86 has no deinterleaving
/// load, so low/high bytes are split with mask+`packus` and the
/// products re-interleaved with `unpack` before XORing into `dst`
/// in place. Returns the number of u16 WORDS processed; the caller
/// runs the remainder scalar. Caller must have verified SSSE3.
#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "ssse3")]
unsafe fn fold_ssse3(nl: &[[u8; 16]; 4], nh: &[[u8; 16]; 4], dst: &mut [u16], src: &[u8]) -> usize {
    use std::arch::x86_64::*;
    let chunks = src.len() / 32;
    if chunks == 0 {
        return 0;
    }
    // SAFETY: SSSE3 is enabled here per #[target_feature], and every
    // caller has verified it at runtime (documented requirement above).
    // All pointer accesses stay within the first chunks * 32 bytes: in
    // bounds for src by chunks = src.len() / 32, and for dst by the
    // caller's guarantee that dst has a word for every byte pair of
    // src (the assert in xor_mul_into).
    unsafe {
        let (t0l, t1l, t2l, t3l) = (
            _mm_loadu_si128(nl[0].as_ptr() as *const __m128i),
            _mm_loadu_si128(nl[1].as_ptr() as *const __m128i),
            _mm_loadu_si128(nl[2].as_ptr() as *const __m128i),
            _mm_loadu_si128(nl[3].as_ptr() as *const __m128i),
        );
        let (t0h, t1h, t2h, t3h) = (
            _mm_loadu_si128(nh[0].as_ptr() as *const __m128i),
            _mm_loadu_si128(nh[1].as_ptr() as *const __m128i),
            _mm_loadu_si128(nh[2].as_ptr() as *const __m128i),
            _mm_loadu_si128(nh[3].as_ptr() as *const __m128i),
        );
        let nib = _mm_set1_epi8(0x0f);
        let lo8 = _mm_set1_epi16(0x00ff);
        let dst_bytes = dst.as_mut_ptr() as *mut u8;
        for c in 0..chunks {
            let sp = src.as_ptr().add(c * 32) as *const __m128i;
            let v0 = _mm_loadu_si128(sp);
            let v1 = _mm_loadu_si128(sp.add(1));
            // Split the 16 words into their low and high bytes.
            let slo = _mm_packus_epi16(_mm_and_si128(v0, lo8), _mm_and_si128(v1, lo8));
            let shi = _mm_packus_epi16(_mm_srli_epi16(v0, 8), _mm_srli_epi16(v1, 8));
            let n0 = _mm_and_si128(slo, nib);
            let n1 = _mm_and_si128(_mm_srli_epi16(slo, 4), nib);
            let n2 = _mm_and_si128(shi, nib);
            let n3 = _mm_and_si128(_mm_srli_epi16(shi, 4), nib);
            let plo = _mm_xor_si128(
                _mm_xor_si128(_mm_shuffle_epi8(t0l, n0), _mm_shuffle_epi8(t1l, n1)),
                _mm_xor_si128(_mm_shuffle_epi8(t2l, n2), _mm_shuffle_epi8(t3l, n3)),
            );
            let phi = _mm_xor_si128(
                _mm_xor_si128(_mm_shuffle_epi8(t0h, n0), _mm_shuffle_epi8(t1h, n1)),
                _mm_xor_si128(_mm_shuffle_epi8(t2h, n2), _mm_shuffle_epi8(t3h, n3)),
            );
            // Re-interleave the product bytes into word order; the XOR
            // into dst then needs no deinterleave at all.
            let dp = dst_bytes.add(c * 32) as *mut __m128i;
            let d0 = _mm_loadu_si128(dp);
            let d1 = _mm_loadu_si128(dp.add(1));
            _mm_storeu_si128(dp, _mm_xor_si128(d0, _mm_unpacklo_epi8(plo, phi)));
            _mm_storeu_si128(dp.add(1), _mm_xor_si128(d1, _mm_unpackhi_epi8(plo, phi)));
        }
    }
    chunks * 16
}

/// AVX2 fold: the SSSE3 path widened to 32 words per 64-byte chunk -
/// `vpshufb` shuffles each 128-bit lane against its own copy of the
/// broadcast nibble table, and `packus`/`unpack` are lane-local too,
/// so the split/lookup/re-interleave round-trips within each lane
/// exactly as in the 128-bit version. Returns u16 WORDS processed;
/// caller runs the remainder scalar. Caller must have verified AVX2.
#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx2")]
unsafe fn fold_avx2(nl: &[[u8; 16]; 4], nh: &[[u8; 16]; 4], dst: &mut [u16], src: &[u8]) -> usize {
    use std::arch::x86_64::*;
    let chunks = src.len() / 64;
    if chunks == 0 {
        return 0;
    }
    // SAFETY: AVX2 is enabled here per #[target_feature], and every
    // caller has verified it at runtime (documented requirement above).
    // All pointer accesses stay within the first chunks * 64 bytes: in
    // bounds for src by chunks = src.len() / 64, and for dst by the
    // caller's guarantee that dst has a word for every byte pair of
    // src (the assert in xor_mul_into).
    unsafe {
        let bc = |t: &[u8; 16]| {
            _mm256_broadcastsi128_si256(_mm_loadu_si128(t.as_ptr() as *const __m128i))
        };
        let (t0l, t1l, t2l, t3l) = (bc(&nl[0]), bc(&nl[1]), bc(&nl[2]), bc(&nl[3]));
        let (t0h, t1h, t2h, t3h) = (bc(&nh[0]), bc(&nh[1]), bc(&nh[2]), bc(&nh[3]));
        let nib = _mm256_set1_epi8(0x0f);
        let lo8 = _mm256_set1_epi16(0x00ff);
        let dst_bytes = dst.as_mut_ptr() as *mut u8;
        for c in 0..chunks {
            let sp = src.as_ptr().add(c * 64) as *const __m256i;
            let v0 = _mm256_loadu_si256(sp);
            let v1 = _mm256_loadu_si256(sp.add(1));
            let slo = _mm256_packus_epi16(_mm256_and_si256(v0, lo8), _mm256_and_si256(v1, lo8));
            let shi = _mm256_packus_epi16(_mm256_srli_epi16(v0, 8), _mm256_srli_epi16(v1, 8));
            let n0 = _mm256_and_si256(slo, nib);
            let n1 = _mm256_and_si256(_mm256_srli_epi16(slo, 4), nib);
            let n2 = _mm256_and_si256(shi, nib);
            let n3 = _mm256_and_si256(_mm256_srli_epi16(shi, 4), nib);
            let plo = _mm256_xor_si256(
                _mm256_xor_si256(_mm256_shuffle_epi8(t0l, n0), _mm256_shuffle_epi8(t1l, n1)),
                _mm256_xor_si256(_mm256_shuffle_epi8(t2l, n2), _mm256_shuffle_epi8(t3l, n3)),
            );
            let phi = _mm256_xor_si256(
                _mm256_xor_si256(_mm256_shuffle_epi8(t0h, n0), _mm256_shuffle_epi8(t1h, n1)),
                _mm256_xor_si256(_mm256_shuffle_epi8(t2h, n2), _mm256_shuffle_epi8(t3h, n3)),
            );
            let dp = dst_bytes.add(c * 64) as *mut __m256i;
            let d0 = _mm256_loadu_si256(dp);
            let d1 = _mm256_loadu_si256(dp.add(1));
            _mm256_storeu_si256(dp, _mm256_xor_si256(d0, _mm256_unpacklo_epi8(plo, phi)));
            _mm256_storeu_si256(
                dp.add(1),
                _mm256_xor_si256(d1, _mm256_unpackhi_epi8(plo, phi)),
            );
        }
    }
    chunks * 32
}

/// GFNI+AVX2 fold: the AVX2 nibble path with the 8 table shuffles
/// replaced by 4 `gf2p8affineqb`s against the four 8x8 bit-matrices
/// in `affine` (see [`MulTable::affine`]) - same split/re-interleave
/// framing, half the shuffle-port traffic and no nibble extraction.
/// Returns u16 WORDS processed; caller runs the remainder scalar.
/// Caller must have verified GFNI and AVX2.
#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "gfni,avx2")]
unsafe fn fold_gfni(affine: &[u64; 4], dst: &mut [u16], src: &[u8]) -> usize {
    use std::arch::x86_64::*;
    let chunks = src.len() / 64;
    if chunks == 0 {
        return 0;
    }
    // SAFETY: GFNI and AVX2 are enabled here per #[target_feature],
    // and every caller has verified both at runtime (documented
    // requirement above). All pointer accesses stay within the first
    // chunks * 64 bytes: in bounds for src by chunks = src.len() / 64,
    // and for dst by the caller's guarantee that dst has a word for
    // every byte pair of src (the assert in xor_mul_into).
    unsafe {
        let mll = _mm256_set1_epi64x(affine[0] as i64);
        let mhl = _mm256_set1_epi64x(affine[1] as i64);
        let mlh = _mm256_set1_epi64x(affine[2] as i64);
        let mhh = _mm256_set1_epi64x(affine[3] as i64);
        let lo8 = _mm256_set1_epi16(0x00ff);
        let dst_bytes = dst.as_mut_ptr() as *mut u8;
        for c in 0..chunks {
            let sp = src.as_ptr().add(c * 64) as *const __m256i;
            let v0 = _mm256_loadu_si256(sp);
            let v1 = _mm256_loadu_si256(sp.add(1));
            let slo = _mm256_packus_epi16(_mm256_and_si256(v0, lo8), _mm256_and_si256(v1, lo8));
            let shi = _mm256_packus_epi16(_mm256_srli_epi16(v0, 8), _mm256_srli_epi16(v1, 8));
            let plo = _mm256_xor_si256(
                _mm256_gf2p8affine_epi64_epi8::<0>(slo, mll),
                _mm256_gf2p8affine_epi64_epi8::<0>(shi, mhl),
            );
            let phi = _mm256_xor_si256(
                _mm256_gf2p8affine_epi64_epi8::<0>(slo, mlh),
                _mm256_gf2p8affine_epi64_epi8::<0>(shi, mhh),
            );
            let dp = dst_bytes.add(c * 64) as *mut __m256i;
            let d0 = _mm256_loadu_si256(dp);
            let d1 = _mm256_loadu_si256(dp.add(1));
            _mm256_storeu_si256(dp, _mm256_xor_si256(d0, _mm256_unpacklo_epi8(plo, phi)));
            _mm256_storeu_si256(
                dp.add(1),
                _mm256_xor_si256(d1, _mm256_unpackhi_epi8(plo, phi)),
            );
        }
    }
    chunks * 32
}

impl MulTable {
    /// dst ^= c · src over u16 word slices (used by matrix row ops and
    /// the repair back-substitution). On little-endian targets the word
    /// slice IS its PAR2 byte representation, so this rides the same
    /// SIMD fold as [`xor_mul_into`](Self::xor_mul_into).
    pub fn xor_mul_words(&self, dst: &mut [u16], src: &[u16]) {
        #[cfg(target_endian = "little")]
        {
            let n = src.len().min(dst.len());
            self.xor_mul_into(&mut dst[..n], words_as_bytes(&src[..n]));
        }
        #[cfg(target_endian = "big")]
        for (d, s) in dst.iter_mut().zip(src) {
            *d ^= self.mul(*s);
        }
    }
}

/// The fold-only slice of [`MulTable`]: exactly the fields the SIMD
/// fold kernels read - the nibble tables (128 B) plus, on x86_64, the
/// GFNI bit-matrices (32 B) - against 1.2 KB for the full table. The
/// tiled repair fold builds one table per (row, source) and walks the
/// whole set across every column tile, so the tables compete with the
/// destination tiles for cache; shrinking them ~9x cuts that streaming
/// footprint and lets ~9x more sources share one table-budget group
/// (fewer passes over the destination tiles). The scalar matrix paths
/// (inversion, Vandermonde) keep [`MulTable`]: a 256-entry split table
/// is what makes single-word [`mul`](MulTable::mul) fast, and this
/// type deliberately has no such method.
///
/// On targets with no SIMD fold the split tables ARE the whole fold,
/// so there this type keeps them and the split is a no-op.
pub struct FoldTable {
    #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
    nl: [[u8; 16]; 4],
    #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
    nh: [[u8; 16]; 4],
    #[cfg(target_arch = "x86_64")]
    affine: [u64; 4],
    #[cfg(not(any(target_arch = "aarch64", target_arch = "x86_64")))]
    lo: [u16; 256],
    #[cfg(not(any(target_arch = "aarch64", target_arch = "x86_64")))]
    hi: [u16; 256],
}

impl FoldTable {
    /// Also much cheaper to BUILD than [`MulTable::new`]: 64 field
    /// multiplies (plus, on x86_64, the nibble-table affine lookup)
    /// instead of 512 - the fold builds one per (row, source).
    pub fn new(c: u16) -> FoldTable {
        #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
        {
            let (nl, nh) = nibble_tables(c);
            FoldTable {
                nl,
                nh,
                #[cfg(target_arch = "x86_64")]
                affine: affine_matrices_fast(c),
            }
        }
        #[cfg(not(any(target_arch = "aarch64", target_arch = "x86_64")))]
        {
            let mut lo = [0u16; 256];
            let mut hi = [0u16; 256];
            for b in 0..256u16 {
                lo[b as usize] = mul(c, b);
                hi[b as usize] = mul(c, b << 8);
            }
            FoldTable { lo, hi }
        }
    }

    /// [`MulTable::xor_mul_into`] with the compact tables: the same
    /// SIMD kernels, with the sub-chunk tail finished from the nibble
    /// tables (at most 15 words plus an odd byte, so their 8-lookup
    /// word cost never matters; on a pre-SSSE3 x86 the whole buffer
    /// would run that way - keep [`MulTable`] anywhere that matters).
    pub fn xor_mul_into(&self, dst: &mut [u16], src: &[u8]) {
        assert!(src.len().div_ceil(2) <= dst.len(), "src longer than dst");
        #[cfg(target_arch = "aarch64")]
        let done = fold_simd(&self.nl, &self.nh, dst, src);
        #[cfg(target_arch = "x86_64")]
        let done = fold_simd(&self.nl, &self.nh, &self.affine, dst, src);
        #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
        Self::xor_mul_scalar_nibble(&self.nl, &self.nh, &mut dst[done..], &src[done * 2..]);
        #[cfg(not(any(target_arch = "aarch64", target_arch = "x86_64")))]
        MulTable::xor_mul_scalar(&self.lo, &self.hi, dst, src);
    }

    /// The scalar tail from the nibble tables (layout per
    /// [`MulTable::nl`]): a word's product is the XOR of its four
    /// nibbles' table entries, per byte half.
    #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
    fn xor_mul_scalar_nibble(nl: &[[u8; 16]; 4], nh: &[[u8; 16]; 4], dst: &mut [u16], src: &[u8]) {
        let mul1 = |w: u16| -> u16 {
            let n = [
                (w & 0xf) as usize,
                ((w >> 4) & 0xf) as usize,
                ((w >> 8) & 0xf) as usize,
                (w >> 12) as usize,
            ];
            let lo = nl[0][n[0]] ^ nl[1][n[1]] ^ nl[2][n[2]] ^ nl[3][n[3]];
            let hi = nh[0][n[0]] ^ nh[1][n[1]] ^ nh[2][n[2]] ^ nh[3][n[3]];
            lo as u16 | (hi as u16) << 8
        };
        let words = src.len() / 2;
        for (d, s) in dst.iter_mut().zip(src.as_chunks::<2>().0) {
            *d ^= mul1(u16::from_le_bytes(*s));
        }
        if src.len() % 2 == 1 {
            dst[words] ^= mul1(src[src.len() - 1] as u16);
        }
    }
}

/// How many sources [`xor_mul_multi_into`] fuses per pass on this
/// build, or 0 when no multi kernel exists and callers should stay on
/// the per-source [`MulTable`] path.
pub fn multi_fold_width() -> usize {
    // `NZBFAST_GF16_MULTI=0` forces the single-source path on any
    // arch - the A/B knob for a kernel change, read once. Not a
    // setting; nothing ships it.
    static OFF: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    if *OFF.get_or_init(|| std::env::var_os("NZBFAST_GF16_MULTI").is_some_and(|v| v == "0")) {
        return 0;
    }
    #[cfg(target_arch = "aarch64")]
    {
        8
    }
    #[cfg(target_arch = "x86_64")]
    {
        if avx512_gfni_available() {
            // 32 zmm registers: 12 matrix pairs, two accumulators, data
            // and the two shuffle masks fill it the way 6 pairs fill the
            // 16-ymm file below.
            return 12;
        }
        if is_x86_feature_detected!("gfni") && is_x86_feature_detected!("avx2") {
            // The affine2x group width: 6 matrix PAIRS plus the two
            // accumulators, the data register and the deinterleave mask
            // fill the 16-ymm register file exactly (ParPar's
            // AFFINE2X_AMD64_INTERLEAVE is 6 for the same reason).
            // Wider groups would spill the hoisted matrices back to L1,
            // which is precisely the traffic the layout removes.
            return 6;
        }
        if is_x86_feature_detected!("avx2") || is_x86_feature_detected!("ssse3") {
            // The nibble-shuffle kernels: 8 table vectors per source, so
            // past four sources the tables are memory operands to
            // `pshufb` anyway and a wider group buys nothing - the win is
            // one destination load/store per group instead of per source.
            return 4;
        }
        0
    }
    #[cfg(not(any(target_arch = "aarch64", target_arch = "x86_64")))]
    {
        0
    }
}

/// How many u16 WORDS a scheduler must align its tiles and column
/// boundaries to so [`xor_mul_multi_into`]'s selected kernel covers whole
/// units, given that kernel's fan-in from [`multi_fold_width`].
///
/// This is NOT the fan-in. Fan-in is how many SOURCES a pass fuses; this
/// is how many destination words one kernel chunk consumes, and the two
/// only coincide by accident:
///
/// | selected kernel | fan-in | chunk | granule |
/// |---|---:|---:|---:|
/// | AArch64 NEON/PMULL | 8 | 32 B | 16 words |
/// | x86 GFNI + AVX2 | 6 | 32 B | 16 words |
/// | x86 AVX-512 + GFNI | 12 | 64 B | 32 words |
/// | x86 AVX2 nibble | 4 | 64 B + 32 B tail | 16 words |
/// | x86 SSSE3 nibble | 4 | 32 B | 16 words |
///
/// A schedule finer than the granule leaves every unit 16 words short of
/// a full chunk, and those words fall to the caller's per-source
/// remainder path - which rebuilds a fold table per (row, group, source)
/// for every tile and column unit, the 7-25x fold collapse
/// [`super::par2repair`]'s scheduler comments describe.
///
/// The AVX2 nibble kernel's WIDE BODY consumes 64 bytes, and until
/// 3 Sep 2026 that was a real mismatch against the 16 it is scheduled
/// at: a 16-word unit reached no chunk, so it was not merely misaligned
/// but fell whole to the per-source remainder path, and
/// `schedule_granule_is_the_selected_kernels_chunk` failed on the first
/// AVX2-without-GFNI host to run it (the 4-vCPU x86-64 CI runner - the
/// two boxes the granule was developed on are aarch64 and AVX-512 GFNI).
/// It was closed at the KERNEL rather than here, by teaching
/// [`xor_mul_multi_avx2`] to finish a trailing 32-byte unit at half
/// width, so the kernel now consumes this granule whole.
///
/// **16 IS SCORED, not deferred.** The sweep that first asked whether it
/// should be 32 could not clear its own neutral control on an i5-10600KF
/// (AVX2, no GFNI) - that host read 0.387x..1.989x with the geometry
/// UNCHANGED - and left the question open for a quiet box. The box was
/// never the problem: re-run on the same host 4 Sep 2026 under a
/// protocol whose A/A is flat there (arms mirrored A B B A inside a
/// round with an idle settle between legs - `bench/component`'s
/// `par2-round.ps1` and the round-40 finding in
/// `research/RAR-PERF-AUDIT-2026-09-02.md` that a back-to-back pair of
/// big writes latches for a whole run with a random sign), every shape
/// of the 16-against-32 A/B landed inside that protocol's own A/A
/// envelope, on the fold microbenchmark and at the shipped repair
/// shapes alike.
///
/// AND THE NULL IS STRUCTURAL, which is the part worth carrying: the
/// granule reaches only two numbers, `fold_parallel`'s `col_chunk` and
/// `fold_chunk_multi`'s `tile_words`, and both already land on a
/// multiple of 32 words at nearly every row count, so widening the
/// granule leaves the schedule BIT-IDENTICAL at most shapes - the
/// 1,500-block heavy leg included - and moves it by one 16-word step at
/// the rest. There is no geometry here for 32 to buy, and there is a
/// reason not to claim it anyway: `granule == the selected kernel's
/// chunk` is what `schedule_granule_is_the_selected_kernels_chunk`
/// pins, and this kernel's chunk is 16. Widening the constant alone
/// would be a false statement about the kernel, not a wider schedule.
/// Numbers, raw legs and the derivation:
/// `research/PAR2-PERF-AUDIT-2026-09-02.md` section 22h, which names the
/// archive the legs are in.
/// The first fix, and the Zen 4 rows that accepted the AVX-512 arm:
/// `research/codex-par2-artifacts-2026-09-03/GF16-ALIGN-AUDIT.md`.
pub fn multi_fold_schedule_granule_words(fan_in: usize) -> usize {
    // `NZBFAST_GF16_GRANULE` (16 or 32) forces the schedule width, which
    // is what makes a geometry A/B ONE binary rather than two builds -
    // and the digest trap `research/PAR2-RIGS-2026-09-02.md` records (an
    // arm that is secretly the baseline) is unreachable when both arms
    // are the same executable. Any other value is ignored: the two
    // literals are the only chunk widths a kernel here consumes, and
    // `fold_chunk_multi` masks with `granule - 1`, so a non-power-of-two
    // would be a correctness bug rather than a slower schedule. Read
    // once. Both settings are CORRECT on every arm - 32 is a multiple of
    // the 16-word unit the narrowest kernel consumes, so a wider
    // schedule only moves work between the fused kernel and the caller's
    // remainder path - which is why this is a performance question and
    // an A/B can settle it.
    static FORCED: std::sync::OnceLock<Option<usize>> = std::sync::OnceLock::new();
    if let Some(g) = *FORCED.get_or_init(|| {
        std::env::var("NZBFAST_GF16_GRANULE")
            .ok()
            .and_then(|v| v.parse::<usize>().ok())
            .filter(|g| *g == 16 || *g == 32)
    }) {
        return g;
    }
    // Keyed on the SELECTED kernel's fan-in rather than a fresh hardware
    // probe, so both A/B knobs land back on the old geometry with no
    // extra dispatch query: `NZBFAST_GF16_AVX512=0` selects 6 and
    // `NZBFAST_GF16_MULTI=0` selects 0. On ARM and every non-x86 build
    // this compiles to the literal 16.
    #[cfg(target_arch = "x86_64")]
    if fan_in == 12 {
        // The twelve-source arm is the 512-bit GFNI kernel, and only it.
        return 32;
    }
    #[cfg(not(target_arch = "x86_64"))]
    let _ = fan_in;
    16
}

/// Multi-source fused fold: `dst[i] ^= Σ_s coeffs[s] · src_s[i]`, the
/// technique that makes ParPar's fold fast at high row counts (ours
/// previously re-loaded and re-stored `dst` once per source; this loads
/// each 32-byte chunk once, streams every source's contribution through
/// registers, and stores once - accumulator memory traffic divided by
/// the group width).
///
/// The aarch64 kernel is a port of ParPar's GF16_CLMUL method (public
/// domain, github.com/animetosho/ParPar, gf16_clmul_neon*): per source,
/// a Karatsuba carry-less multiply - lo·c_lo, hi·c_hi and
/// (lo^hi)·(c_lo^c_hi) via `pmull` - accumulated across all sources in
/// six vector registers, then ONE Barrett reduction mod 0x1100B per
/// chunk. No lookup tables at all: a coefficient is three splatted
/// bytes, so the per-(row, source) table builds (and their cache
/// footprint) vanish from the fold entirely.
///
/// Every source must cover `dst`'s full byte length (the fold windows
/// sources per tile and routes short tails through the single-source
/// path). Zero coefficients are fine (they just waste the multiplies).
/// Processes whole 32-byte chunks; returns u16 WORDS processed - the
/// caller runs the remainder per source.
pub fn xor_mul_multi_into(dst: &mut [u16], srcs: &[&[u8]], coeffs: &[u16]) -> usize {
    debug_assert_eq!(srcs.len(), coeffs.len());
    debug_assert!(srcs.iter().all(|s| s.len() >= dst.len() * 2));
    #[cfg(target_arch = "aarch64")]
    {
        // Recovery exponent 0 makes every source coefficient exactly 1.
        // Multiplication by 1 is bytewise identity, so running that row
        // through Karatsuba PMULL plus Barrett reduction is pure overhead.
        // Keep the same fused multi-source memory shape (one destination
        // load/store per group) and XOR the sources directly instead.
        if coeffs.len() == srcs.len() && coeffs.iter().all(|&c| c == 1) {
            // SAFETY: plain NEON is baseline on aarch64; the kernel clamps
            // its chunk range to the shortest source.
            return unsafe { xor_multi_neon(dst, srcs) };
        }
        if std::arch::is_aarch64_feature_detected!("sha3") {
            // SAFETY: sha3 verified by the detect above (NEON is baseline
            // on aarch64); every source covers dst's full byte length, the
            // documented precondition debug_asserted above.
            return unsafe { xor_mul_multi_neon_sha3(dst, srcs, coeffs) };
        }
        // SAFETY: plain NEON (incl. pmull on poly8) is baseline on
        // aarch64, no feature check needed; source coverage as above.
        unsafe { xor_mul_multi_neon(dst, srcs, coeffs) }
    }
    #[cfg(target_arch = "x86_64")]
    {
        // The direct-XOR shortcut only pays when it is at least as WIDE as
        // the GF kernel it replaces. The 512-bit GFNI arm already does a
        // multiply in 64 bytes an instruction, where the widest XOR kernel
        // here does 32, so on a part that has it the shortcut retires MORE
        // instructions than the multiply it skips - measured +0.34% on a
        // three-block repair and +0.55% on a 1,500-block one, Zen 4 EPYC
        // (research/PAR2-TWO-LANES-COMPARED-2026-09-03.md). Everything
        // narrower than that is faster XORing.
        //
        // The predicate is the HARDWARE probe and not `multi_fold_width()
        // == 12`, even though on this arch those agree on every shipping
        // configuration, because the kernel this shortcut displaces is the
        // literal next arm of this same if-chain and that arm is chosen by
        // `avx512_gfni_available()`. `multi_fold_width()` is a different
        // question - it answers what the FOLD SCHEDULER groups by, and
        // `NZBFAST_GF16_MULTI=0` zeroes it without disabling the 512-bit
        // arm below. Under that knob `par2ntt::fold_into` and
        // `forney`'s stage one still call this function directly, still
        // land on `xor_mul_multi_gfni512`, and a width-based predicate
        // would re-enable the shortcut against exactly the kernel it must
        // not race. Keep it reading the same fact the arm below reads.
        if coeffs.len() == srcs.len() && coeffs.iter().all(|&c| c == 1) && !avx512_gfni_available()
        {
            if is_x86_feature_detected!("avx2") {
                // SAFETY: AVX2 verified above; the kernel clamps its chunk
                // range to the shortest source.
                return unsafe { xor_multi_avx2(dst, srcs) };
            }
            // SAFETY: SSE2 is baseline on x86_64; the kernel clamps its
            // chunk range to the shortest source.
            return unsafe { xor_multi_sse2(dst, srcs) };
        }
        if avx512_gfni_available() {
            // SAFETY: AVX-512F/BW and GFNI verified by the detect; the
            // kernel clamps its chunk range to the shortest source.
            return unsafe { xor_mul_multi_gfni512(dst, srcs, coeffs) };
        }
        if is_x86_feature_detected!("gfni") && is_x86_feature_detected!("avx2") {
            // SAFETY: GFNI and AVX2 verified by the detect above; the
            // kernel clamps its chunk range to the shortest source, so it
            // never reads or writes past any slice.
            return unsafe { xor_mul_multi_gfni(dst, srcs, coeffs) };
        }
        if is_x86_feature_detected!("avx2") {
            // SAFETY: AVX2 verified by the detect above; the kernel clamps
            // its chunk range to the shortest source.
            return unsafe { xor_mul_multi_avx2(dst, srcs, coeffs) };
        }
        if is_x86_feature_detected!("ssse3") {
            // SAFETY: SSSE3 verified by the detect above; same clamp.
            return unsafe { xor_mul_multi_ssse3(dst, srcs, coeffs) };
        }
        let _ = (dst, srcs, coeffs);
        0
    }
    #[cfg(not(any(target_arch = "aarch64", target_arch = "x86_64")))]
    {
        let _ = (dst, srcs, coeffs);
        0
    }
}

/// Coefficient-one specialization of the aarch64 multi-source fold.
/// Processes the same 32-byte chunks as the GF kernel and returns u16
/// words consumed so its caller's existing remainder path stays valid.
#[cfg(target_arch = "aarch64")]
unsafe fn xor_multi_neon(dst: &mut [u16], srcs: &[&[u8]]) -> usize {
    use std::arch::aarch64::*;
    let usable = srcs
        .iter()
        .map(|src| src.len())
        .min()
        .unwrap_or(0)
        .min(dst.len().saturating_mul(2));
    let chunks = usable / 32;
    if chunks == 0 || srcs.is_empty() {
        return 0;
    }
    // SAFETY: NEON is baseline on aarch64. `usable` is clamped to both the
    // destination byte length and the shortest source, so every 32-byte
    // vector is in bounds.
    unsafe {
        let dst_bytes = dst.as_mut_ptr().cast::<u8>();
        for ch in 0..chunks {
            let off = ch * 32;
            let mut a = vld1q_u8(dst_bytes.add(off));
            let mut b = vld1q_u8(dst_bytes.add(off + 16));
            for src in srcs {
                a = veorq_u8(a, vld1q_u8(src.as_ptr().add(off)));
                b = veorq_u8(b, vld1q_u8(src.as_ptr().add(off + 16)));
            }
            vst1q_u8(dst_bytes.add(off), a);
            vst1q_u8(dst_bytes.add(off + 16), b);
        }
    }
    chunks * 16
}

/// Coefficient-one specialization for AVX2 machines.
#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx2")]
unsafe fn xor_multi_avx2(dst: &mut [u16], srcs: &[&[u8]]) -> usize {
    use std::arch::x86_64::*;
    let usable = srcs
        .iter()
        .map(|src| src.len())
        .min()
        .unwrap_or(0)
        .min(dst.len().saturating_mul(2));
    let chunks = usable / 32;
    if chunks == 0 || srcs.is_empty() {
        return 0;
    }
    // SAFETY: AVX2 is enabled by the caller's runtime check. `usable` is
    // clamped to both the destination byte length and the shortest source,
    // so every unaligned vector is in bounds.
    unsafe {
        let dst_bytes = dst.as_mut_ptr().cast::<u8>();
        for ch in 0..chunks {
            let off = ch * 32;
            let mut acc = _mm256_loadu_si256(dst_bytes.add(off).cast());
            for src in srcs {
                acc = _mm256_xor_si256(acc, _mm256_loadu_si256(src.as_ptr().add(off).cast()));
            }
            _mm256_storeu_si256(dst_bytes.add(off).cast(), acc);
        }
    }
    chunks * 16
}

/// Coefficient-one fallback for baseline x86_64.
#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "sse2")]
unsafe fn xor_multi_sse2(dst: &mut [u16], srcs: &[&[u8]]) -> usize {
    use std::arch::x86_64::*;
    let usable = srcs
        .iter()
        .map(|src| src.len())
        .min()
        .unwrap_or(0)
        .min(dst.len().saturating_mul(2));
    let chunks = usable / 16;
    if chunks == 0 || srcs.is_empty() {
        return 0;
    }
    // SAFETY: SSE2 is baseline on x86_64. `usable` is clamped to both the
    // destination byte length and the shortest source, so each vector is
    // in bounds.
    unsafe {
        let dst_bytes = dst.as_mut_ptr().cast::<u8>();
        for ch in 0..chunks {
            let off = ch * 16;
            let mut acc = _mm_loadu_si128(dst_bytes.add(off).cast());
            for src in srcs {
                acc = _mm_xor_si128(acc, _mm_loadu_si128(src.as_ptr().add(off).cast()));
            }
            _mm_storeu_si128(dst_bytes.add(off).cast(), acc);
        }
    }
    chunks * 8
}

/// The four `gf2p8affineqb` matrices for multiply-by-`c` (see
/// [`MulTable::affine`]) without building the rest of the table - the
/// multi-source fold needs ONLY these 32 bytes per (row, source), not
/// the 1.2 KB split tables.
#[cfg(target_arch = "x86_64")]
fn affine_matrices(c: u16) -> [u64; 4] {
    let mut lo_basis = [0u16; 8];
    let mut hi_basis = [0u16; 8];
    for j in 0..8 {
        lo_basis[j] = mul(c, 1 << j);
        hi_basis[j] = mul(c, 1 << (8 + j));
    }
    [
        affine_matrix(&lo_basis, |p| p as u8),
        affine_matrix(&hi_basis, |p| p as u8),
        affine_matrix(&lo_basis, |p| (p >> 8) as u8),
        affine_matrix(&hi_basis, |p| (p >> 8) as u8),
    ]
}

/// The four multiply-by-`c` bit-matrices are GF(2)-LINEAR in `c`
/// (`mul(a ^ b, w) = mul(a, w) ^ mul(b, w)`), so the matrices for any
/// coefficient are the XOR of four table entries, one per nibble of `c`
/// - ParPar's `gf16_bitdep_init256` trick. 64 entries x 32 bytes = 2 KiB,
/// built once. The fold calls this once per (row, tile, source): the
/// from-scratch [`affine_matrices`] build (~hundreds of scalar ops) was
/// a measurable fraction of every small-tile fold call; this is 12 XORs.
#[cfg(target_arch = "x86_64")]
fn affine_bitdep() -> &'static [[[u64; 4]; 16]; 4] {
    static T: OnceLock<[[[u64; 4]; 16]; 4]> = OnceLock::new();
    T.get_or_init(|| {
        let mut t = [[[0u64; 4]; 16]; 4];
        for (p, tp) in t.iter_mut().enumerate() {
            for (v, e) in tp.iter_mut().enumerate() {
                *e = affine_matrices((v as u16) << (4 * p));
            }
        }
        t
    })
}

/// [`affine_matrices`] via the nibble table: 4 lookups + 12 XORs.
#[cfg(target_arch = "x86_64")]
#[inline]
fn affine_matrices_fast(c: u16) -> [u64; 4] {
    let t = affine_bitdep();
    let a = &t[0][(c & 0xf) as usize];
    let b = &t[1][((c >> 4) & 0xf) as usize];
    let d = &t[2][((c >> 8) & 0xf) as usize];
    let e = &t[3][(c >> 12) as usize];
    [
        a[0] ^ b[0] ^ d[0] ^ e[0],
        a[1] ^ b[1] ^ d[1] ^ e[1],
        a[2] ^ b[2] ^ d[2] ^ e[2],
        a[3] ^ b[3] ^ d[3] ^ e[3],
    ]
}

/// Whether the 512-bit GFNI fold may run: the ISA bits, and not
/// `NZBFAST_GF16_AVX512=0`, the A/B knob against the 256-bit kernel on
/// the same box. Read once.
#[cfg(target_arch = "x86_64")]
fn avx512_gfni_available() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| {
        !std::env::var_os("NZBFAST_GF16_AVX512").is_some_and(|v| v == "0")
            && is_x86_feature_detected!("avx512f")
            && is_x86_feature_detected!("avx512bw")
            && is_x86_feature_detected!("gfni")
    })
}

/// The 512-bit twin of [`xor_mul_multi_gfni`]: the same affine2x layout
/// per 128-bit lane (everything in that kernel is lane-local, which is
/// what makes this a widening and not a redesign), four lanes per
/// register, 64-byte chunks, groups of twelve sources. TODO 52 parked
/// this on "no hardware to run it"; an 8-vCPU Zen 4 EPYC became
/// reachable in Sep 2026 and is where it was measured. Zen 4 runs most
/// 512-bit ops double-pumped, so the gain there is front-end and load
/// width rather than raw ALU width (+5-7% at 1,500 rows, flat below);
/// Zen 5 and Ice Lake+ have the full datapath.
/// Returns u16 WORDS processed (whole 64-byte chunks).
#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "gfni,avx512f,avx512bw")]
unsafe fn xor_mul_multi_gfni512(dst: &mut [u16], srcs: &[&[u8]], coeffs: &[u16]) -> usize {
    if srcs.is_empty() {
        return 0;
    }
    let usable = srcs.iter().fold(dst.len() * 2, |m, s| m.min(s.len()));
    let chunks = usable / 64;
    if chunks == 0 {
        return 0;
    }
    let mut g0 = 0usize;
    while g0 < srcs.len() {
        let g1 = (g0 + 12).min(srcs.len());
        let s = &srcs[g0..g1];
        let c = &coeffs[g0..g1];
        // SAFETY: the target features are enabled on this fn (runtime-
        // verified at the dispatch site); `chunks` is clamped to the
        // shortest source and to dst's byte length.
        unsafe {
            match g1 - g0 {
                1 => xor_mul_multi_gfni512_n::<1>(dst, s, c, chunks),
                2 => xor_mul_multi_gfni512_n::<2>(dst, s, c, chunks),
                3 => xor_mul_multi_gfni512_n::<3>(dst, s, c, chunks),
                4 => xor_mul_multi_gfni512_n::<4>(dst, s, c, chunks),
                5 => xor_mul_multi_gfni512_n::<5>(dst, s, c, chunks),
                6 => xor_mul_multi_gfni512_n::<6>(dst, s, c, chunks),
                7 => xor_mul_multi_gfni512_n::<7>(dst, s, c, chunks),
                8 => xor_mul_multi_gfni512_n::<8>(dst, s, c, chunks),
                9 => xor_mul_multi_gfni512_n::<9>(dst, s, c, chunks),
                10 => xor_mul_multi_gfni512_n::<10>(dst, s, c, chunks),
                11 => xor_mul_multi_gfni512_n::<11>(dst, s, c, chunks),
                _ => xor_mul_multi_gfni512_n::<12>(dst, s, c, chunks),
            }
        }
        g0 = g1;
    }
    chunks * 32
}

#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "gfni,avx512f,avx512bw")]
unsafe fn xor_mul_multi_gfni512_n<const N: usize>(
    dst: &mut [u16],
    srcs: &[&[u8]],
    coeffs: &[u16],
    chunks: usize,
) {
    use std::arch::x86_64::*;
    debug_assert_eq!(srcs.len(), N);
    debug_assert!(srcs.iter().all(|s| s.len() >= chunks * 64));
    // SAFETY: gfni+avx512f+avx512bw are enabled here per
    // #[target_feature] (runtime-verified at the dispatch site). All
    // pointer accesses stay within the first chunks * 64 bytes of each
    // slice: the caller clamps `chunks` to the shortest source and to
    // dst's byte length, per the debug_asserts above.
    unsafe {
        let mut mat_n = [_mm512_setzero_si512(); N];
        let mut mat_s = [_mm512_setzero_si512(); N];
        let mut src_ptr = [std::ptr::null::<u8>(); N];
        for s in 0..N {
            let m = affine_matrices_fast(coeffs[s]);
            // Qword lanes 0/2/4/6 act on low-byte qwords, 1/3/5/7 on
            // high-byte qwords - the 256-bit pattern, twice.
            mat_n[s] = _mm512_set_epi64(
                m[3] as i64,
                m[0] as i64,
                m[3] as i64,
                m[0] as i64,
                m[3] as i64,
                m[0] as i64,
                m[3] as i64,
                m[0] as i64,
            );
            mat_s[s] = _mm512_set_epi64(
                m[1] as i64,
                m[2] as i64,
                m[1] as i64,
                m[2] as i64,
                m[1] as i64,
                m[2] as i64,
                m[1] as i64,
                m[2] as i64,
            );
            src_ptr[s] = srcs[s].as_ptr();
        }
        let deint = _mm512_broadcast_i32x4(_mm_setr_epi8(
            0, 2, 4, 6, 8, 10, 12, 14, 1, 3, 5, 7, 9, 11, 13, 15,
        ));
        let inter = _mm512_broadcast_i32x4(_mm_setr_epi8(
            0, 8, 1, 9, 2, 10, 3, 11, 4, 12, 5, 13, 6, 14, 7, 15,
        ));
        let dst_bytes = dst.as_mut_ptr() as *mut u8;
        for ch in 0..chunks {
            let off = ch * 64;
            let mut acc_n = _mm512_setzero_si512();
            let mut acc_s = _mm512_setzero_si512();
            for s in 0..N {
                let data = _mm512_loadu_si512(src_ptr[s].add(off) as *const __m512i);
                let data = _mm512_shuffle_epi8(data, deint);
                acc_n = _mm512_xor_si512(acc_n, _mm512_gf2p8affine_epi64_epi8::<0>(data, mat_n[s]));
                acc_s = _mm512_xor_si512(acc_s, _mm512_gf2p8affine_epi64_epi8::<0>(data, mat_s[s]));
            }
            // Swap the qwords of each 128-bit lane (BADC), as the 256-bit
            // kernel's 0x4E shuffle does.
            let res = _mm512_xor_si512(acc_n, _mm512_shuffle_epi32::<_MM_PERM_BADC>(acc_s));
            let res = _mm512_shuffle_epi8(res, inter);
            let dp = dst_bytes.add(off) as *mut __m512i;
            _mm512_storeu_si512(dp, _mm512_xor_si512(_mm512_loadu_si512(dp), res));
        }
    }
}

/// GFNI+AVX2 multi-source fold in ParPar's affine2x layout (public
/// domain, github.com/animetosho/ParPar, gf16_affine2x_x86.h +
/// gf16_affine_avx2.c - layout ported, code our own).
///
/// Each 32-byte chunk is deinterleaved ONCE on load (`vpshufb`, ParPar's
/// `separate_low_high`): per 128-bit lane, qword 0 holds the 8 words'
/// low bytes and qword 1 their high bytes. `gf2p8affineqb` applies one
/// 8x8 bit-matrix per qword lane, so multiply-by-c is then TWO affines
/// per source instead of four: matNorm = [lo→lo, hi→hi] computes the
/// same-half contributions in place, matSwap = [lo→hi, hi→lo] the
/// cross-half ones, which come home with a single qword swap. The swap
/// and the re-interleave both distribute over XOR, so they hoist out of
/// the source loop - per source the steady state is one load, one
/// shuffle, two affines and two XORs, with the matrix pairs
/// REGISTER-RESIDENT across the whole chunk loop (the monomorphized
/// source count pins them, exactly like the aarch64 sha3 kernel).
///
/// The previous kernel re-broadcast four matrices per source per chunk
/// from L1 and paid a packus deinterleave per source per chunk; it
/// measured at half ParPar's per-core rate for exactly that reason
/// (24.8 vs 48.3 GB/s on an i7-1280P P-core - the TODO 58 item B
/// decomposition).
///
/// Everything here is 128-bit-LANE-LOCAL (the deinterleave, the qword
/// swap, the matrix pattern): widening to zmm for full-width AVX-512
/// GFNI parts (Zen 4/5) is just broadcasting the same 128-bit patterns
/// wider, per the 2026-07-30 PAR SOTA survey. Keep it that way.
#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "gfni,avx2")]
unsafe fn xor_mul_multi_gfni(dst: &mut [u16], srcs: &[&[u8]], coeffs: &[u16]) -> usize {
    if srcs.is_empty() {
        return 0;
    }
    // Every group must fold the SAME chunk range: the caller finishes
    // `dst[done..]` per source, so a group that ran further than another
    // would leave its extra chunks double-folded. Clamp once, up front,
    // to the shortest source (sources may legally be one byte short of
    // an odd-length dst).
    let usable = srcs.iter().fold(dst.len() * 2, |m, s| m.min(s.len()));
    let chunks = usable / 32;
    if chunks == 0 {
        return 0;
    }
    // Groups of `multi_fold_width` keep the matrix pairs
    // register-resident; a wider call simply takes more passes over the
    // dst tile, as the caller's own grouping would.
    let mut g0 = 0usize;
    while g0 < srcs.len() {
        let g1 = (g0 + 6).min(srcs.len());
        let s = &srcs[g0..g1];
        let c = &coeffs[g0..g1];
        // SAFETY: gfni+avx2 are enabled on this fn per #[target_feature]
        // (runtime-verified at the dispatch site), which covers the
        // callee's requirement; `chunks` was clamped above to the shortest
        // source and to dst's byte length, meeting the callee's bounds
        // contract (its debug_assert).
        unsafe {
            match g1 - g0 {
                1 => xor_mul_multi_gfni_n::<1>(dst, s, c, chunks),
                2 => xor_mul_multi_gfni_n::<2>(dst, s, c, chunks),
                3 => xor_mul_multi_gfni_n::<3>(dst, s, c, chunks),
                4 => xor_mul_multi_gfni_n::<4>(dst, s, c, chunks),
                5 => xor_mul_multi_gfni_n::<5>(dst, s, c, chunks),
                _ => xor_mul_multi_gfni_n::<6>(dst, s, c, chunks),
            }
        }
        g0 = g1;
    }
    chunks * 16
}

/// One register-resident group of the affine2x fold: see
/// [`xor_mul_multi_gfni`]. `N` is the exact source count so LLVM
/// unrolls the source loop and pins the `2·N` matrices in ymm registers
/// (at N = 6 the register file is full - see [`multi_fold_width`]).
#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "gfni,avx2")]
unsafe fn xor_mul_multi_gfni_n<const N: usize>(
    dst: &mut [u16],
    srcs: &[&[u8]],
    coeffs: &[u16],
    chunks: usize,
) {
    use std::arch::x86_64::*;
    debug_assert_eq!(srcs.len(), N);
    debug_assert!(srcs.iter().all(|s| s.len() >= chunks * 32));
    // SAFETY: gfni+avx2 are enabled here per #[target_feature] (runtime-
    // verified at the dispatch site). All pointer accesses stay within the
    // first chunks * 32 bytes of each slice: the caller
    // (xor_mul_multi_gfni) clamps `chunks` to the shortest source and to
    // dst's byte length, per the debug_asserts above.
    unsafe {
        // matNorm/matSwap per source, from the same four 8x8 bit-matrices
        // the single-source path uses ([`affine_matrices`]: [ll, hl, lh,
        // hh] = [lo→lo, hi→lo, lo→hi, hi→hi]). Qword lanes 0/2 act on
        // low-byte qwords, lanes 1/3 on high-byte qwords.
        let mut mat_n = [_mm256_setzero_si256(); N];
        let mut mat_s = [_mm256_setzero_si256(); N];
        let mut src_ptr = [std::ptr::null::<u8>(); N];
        for s in 0..N {
            let m = affine_matrices_fast(coeffs[s]);
            mat_n[s] = _mm256_set_epi64x(m[3] as i64, m[0] as i64, m[3] as i64, m[0] as i64);
            mat_s[s] = _mm256_set_epi64x(m[1] as i64, m[2] as i64, m[1] as i64, m[2] as i64);
            src_ptr[s] = srcs[s].as_ptr();
        }
        // ParPar's separate_low_high / its inverse, per 128-bit lane.
        let deint = _mm256_broadcastsi128_si256(_mm_setr_epi8(
            0, 2, 4, 6, 8, 10, 12, 14, 1, 3, 5, 7, 9, 11, 13, 15,
        ));
        let inter = _mm256_broadcastsi128_si256(_mm_setr_epi8(
            0, 8, 1, 9, 2, 10, 3, 11, 4, 12, 5, 13, 6, 14, 7, 15,
        ));
        let dst_bytes = dst.as_mut_ptr() as *mut u8;
        for ch in 0..chunks {
            let off = ch * 32;
            let mut acc_n = _mm256_setzero_si256();
            let mut acc_s = _mm256_setzero_si256();
            for s in 0..N {
                let data = _mm256_loadu_si256(src_ptr[s].add(off) as *const __m256i);
                let data = _mm256_shuffle_epi8(data, deint);
                acc_n = _mm256_xor_si256(acc_n, _mm256_gf2p8affine_epi64_epi8::<0>(data, mat_n[s]));
                acc_s = _mm256_xor_si256(acc_s, _mm256_gf2p8affine_epi64_epi8::<0>(data, mat_s[s]));
            }
            // 0x4E = _MM_SHUFFLE(1,0,3,2): swap the qwords of each lane,
            // bringing the cross-half contributions home.
            let res = _mm256_xor_si256(acc_n, _mm256_shuffle_epi32::<0x4E>(acc_s));
            let res = _mm256_shuffle_epi8(res, inter);
            let dp = dst_bytes.add(off) as *mut __m256i;
            _mm256_storeu_si256(dp, _mm256_xor_si256(_mm256_loadu_si256(dp), res));
        }
    }
}

/// Multi-source nibble-shuffle fold for x86 WITHOUT GFNI - AVX2 form.
/// The single-source [`fold_avx2`] framing (split each 64-byte chunk
/// into its low and high bytes, four nibble extractions, eight `pshufb`
/// lookups against the [`nibble_tables`] of the coefficient, re-
/// interleave) with the destination load/XOR/store hoisted OUT of the
/// source loop: the low/high product accumulators stay in registers
/// across every source of the group and the destination is touched
/// once per group. This is ParPar's "shuffle" method's multi-region
/// form. Measured 2 Sep 2026 on an i5-10600KF (AVX2, no GFNI): the
/// single-source fold ran the 1,500-block heavy leg 2.7x behind
/// par2cmdline-turbo 1.5.0 (research/PAR2-PERF-AUDIT-2026-09-02.md).
///
/// Every AVX2-without-GFNI part - Intel before Ice Lake, AMD before
/// Zen 4 - takes this path. Returns u16 WORDS processed: whole 64-byte
/// chunks through the 256-bit body plus, when one is left, a final
/// 32-byte unit at half width, so the kernel consumes destinations in
/// 16-word steps and matches the granule
/// [`multi_fold_schedule_granule_words`] gives the scheduler here. The
/// caller finishes the remainder per source.
#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx2")]
unsafe fn xor_mul_multi_avx2(dst: &mut [u16], srcs: &[&[u8]], coeffs: &[u16]) -> usize {
    if srcs.is_empty() {
        return 0;
    }
    // Same clamp as the GFNI kernel: every group must fold the same
    // chunk range, because the caller finishes `dst[done..]` per source.
    let usable = srcs.iter().fold(dst.len() * 2, |m, s| m.min(s.len()));
    // 32-byte UNITS, not the 64-byte chunks the wide body consumes: a
    // trailing 32 bytes is finished at half width inside
    // `xor_mul_multi_avx2_n`, so this kernel's real consumption granule is
    // 32 bytes - the 16 words `multi_fold_schedule_granule_words` hands
    // the fold scheduler on every AVX2-without-GFNI part.
    //
    // Until 3 Sep 2026 this divided by 64 while the scheduler aligned to
    // 16 words, so a destination of exactly one granule reached no chunk
    // at all: `xor_mul_multi_into` returned 0 and the whole unit fell to
    // the caller's per-source remainder path - the fold-table-per-(row,
    // group, source) collapse the granule exists to prevent, on Intel
    // before Ice Lake and AMD before Zen 4. It went unseen because the
    // two parts the granule was developed on are not in that class
    // (Apple aarch64 folds 32-byte chunks, Zen 4 has AVX-512 GFNI and
    // takes the 64-byte arm with a 32-word granule to match), and the
    // 4-vCPU x86-64 CI runner - Cascade Lake or Zen 3, AVX2 and no GFNI -
    // is.
    let units = usable / 32;
    if units == 0 {
        return 0;
    }
    // `NZBFAST_GF16_AVX2_GROUP` (1..4) narrows the group for A/Bs -
    // at 2 the eight table vectors of each source fit the register
    // file beside the accumulators and data. Read once.
    static GROUP: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    let group = *GROUP.get_or_init(|| {
        std::env::var("NZBFAST_GF16_AVX2_GROUP")
            .ok()
            .and_then(|v| v.parse::<usize>().ok())
            .map_or(4, |g| g.clamp(1, 4))
    });
    let mut g0 = 0usize;
    while g0 < srcs.len() {
        let g1 = (g0 + group).min(srcs.len());
        let s = &srcs[g0..g1];
        let c = &coeffs[g0..g1];
        // SAFETY: avx2 is enabled on this fn per #[target_feature]
        // (runtime-verified at the dispatch site); `units` is clamped to
        // the shortest source and to dst's byte length, the callee's
        // bounds contract.
        unsafe {
            match g1 - g0 {
                1 => xor_mul_multi_avx2_n::<1>(dst, s, c, units),
                2 => xor_mul_multi_avx2_n::<2>(dst, s, c, units),
                3 => xor_mul_multi_avx2_n::<3>(dst, s, c, units),
                _ => xor_mul_multi_avx2_n::<4>(dst, s, c, units),
            }
        }
        g0 = g1;
    }
    units * 16
}

#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx2")]
unsafe fn xor_mul_multi_avx2_n<const N: usize>(
    dst: &mut [u16],
    srcs: &[&[u8]],
    coeffs: &[u16],
    units: usize,
) {
    use std::arch::x86_64::*;
    debug_assert_eq!(srcs.len(), N);
    debug_assert!(srcs.iter().all(|s| s.len() >= units * 32));
    // Whole 64-byte chunks for the 256-bit body, then - when `units` is
    // odd - one 32-byte unit at half width below.
    let chunks = units / 2;
    // SAFETY: avx2 is enabled here per #[target_feature] (runtime-
    // verified at the dispatch site). All pointer accesses stay within
    // the first units * 32 bytes of each slice: the caller
    // (xor_mul_multi_avx2) clamps `units` to the shortest source and to
    // dst's byte length, per the debug_asserts above.
    unsafe {
        let bc = |t: &[u8; 16]| {
            _mm256_broadcastsi128_si256(_mm_loadu_si128(t.as_ptr() as *const __m128i))
        };
        // Per source: the four low-byte and four high-byte nibble tables,
        // one 128-bit table broadcast to both lanes. Past one source
        // these are `pshufb` memory operands, which is fine: they stay in
        // L1 and the port that matters is the shuffle port, not a load.
        let mut tl = [[_mm256_setzero_si256(); 4]; N];
        let mut th = [[_mm256_setzero_si256(); 4]; N];
        let mut src_ptr = [std::ptr::null::<u8>(); N];
        for s in 0..N {
            let (nl, nh) = nibble_tables(coeffs[s]);
            for j in 0..4 {
                tl[s][j] = bc(&nl[j]);
                th[s][j] = bc(&nh[j]);
            }
            src_ptr[s] = srcs[s].as_ptr();
        }
        let nib = _mm256_set1_epi8(0x0f);
        let lo8 = _mm256_set1_epi16(0x00ff);
        let dst_bytes = dst.as_mut_ptr() as *mut u8;
        for ch in 0..chunks {
            let off = ch * 64;
            let mut plo = _mm256_setzero_si256();
            let mut phi = _mm256_setzero_si256();
            for s in 0..N {
                let sp = src_ptr[s].add(off) as *const __m256i;
                let v0 = _mm256_loadu_si256(sp);
                let v1 = _mm256_loadu_si256(sp.add(1));
                let slo = _mm256_packus_epi16(_mm256_and_si256(v0, lo8), _mm256_and_si256(v1, lo8));
                let shi = _mm256_packus_epi16(_mm256_srli_epi16(v0, 8), _mm256_srli_epi16(v1, 8));
                let n0 = _mm256_and_si256(slo, nib);
                let n1 = _mm256_and_si256(_mm256_srli_epi16(slo, 4), nib);
                let n2 = _mm256_and_si256(shi, nib);
                let n3 = _mm256_and_si256(_mm256_srli_epi16(shi, 4), nib);
                plo = _mm256_xor_si256(
                    plo,
                    _mm256_xor_si256(
                        _mm256_xor_si256(
                            _mm256_shuffle_epi8(tl[s][0], n0),
                            _mm256_shuffle_epi8(tl[s][1], n1),
                        ),
                        _mm256_xor_si256(
                            _mm256_shuffle_epi8(tl[s][2], n2),
                            _mm256_shuffle_epi8(tl[s][3], n3),
                        ),
                    ),
                );
                phi = _mm256_xor_si256(
                    phi,
                    _mm256_xor_si256(
                        _mm256_xor_si256(
                            _mm256_shuffle_epi8(th[s][0], n0),
                            _mm256_shuffle_epi8(th[s][1], n1),
                        ),
                        _mm256_xor_si256(
                            _mm256_shuffle_epi8(th[s][2], n2),
                            _mm256_shuffle_epi8(th[s][3], n3),
                        ),
                    ),
                );
            }
            let dp = dst_bytes.add(off) as *mut __m256i;
            let d0 = _mm256_loadu_si256(dp);
            let d1 = _mm256_loadu_si256(dp.add(1));
            _mm256_storeu_si256(dp, _mm256_xor_si256(d0, _mm256_unpacklo_epi8(plo, phi)));
            _mm256_storeu_si256(
                dp.add(1),
                _mm256_xor_si256(d1, _mm256_unpackhi_epi8(plo, phi)),
            );
        }
        if !units.is_multiple_of(2) {
            // The odd 32-byte unit, in 128-bit lanes. Identical algebra:
            // `packus`/`unpack` are both per-128-bit-lane in the wide body
            // above, so halving the width changes no byte ordering, and
            // the broadcast tables' low lane IS the 128-bit table (`bc`
            // built them with `_mm256_broadcastsi128_si256`), so
            // `_mm256_castsi256_si128` is free. ssse3 - and so
            // `_mm_shuffle_epi8` - is implied by the avx2 target feature.
            let off = chunks * 64;
            let nib128 = _mm_set1_epi8(0x0f);
            let lo8_128 = _mm_set1_epi16(0x00ff);
            let mut plo = _mm_setzero_si128();
            let mut phi = _mm_setzero_si128();
            for s in 0..N {
                let sp = src_ptr[s].add(off) as *const __m128i;
                let v0 = _mm_loadu_si128(sp);
                let v1 = _mm_loadu_si128(sp.add(1));
                let slo = _mm_packus_epi16(_mm_and_si128(v0, lo8_128), _mm_and_si128(v1, lo8_128));
                let shi = _mm_packus_epi16(_mm_srli_epi16(v0, 8), _mm_srli_epi16(v1, 8));
                let n0 = _mm_and_si128(slo, nib128);
                let n1 = _mm_and_si128(_mm_srli_epi16(slo, 4), nib128);
                let n2 = _mm_and_si128(shi, nib128);
                let n3 = _mm_and_si128(_mm_srli_epi16(shi, 4), nib128);
                let lane = _mm256_castsi256_si128;
                plo = _mm_xor_si128(
                    plo,
                    _mm_xor_si128(
                        _mm_xor_si128(
                            _mm_shuffle_epi8(lane(tl[s][0]), n0),
                            _mm_shuffle_epi8(lane(tl[s][1]), n1),
                        ),
                        _mm_xor_si128(
                            _mm_shuffle_epi8(lane(tl[s][2]), n2),
                            _mm_shuffle_epi8(lane(tl[s][3]), n3),
                        ),
                    ),
                );
                phi = _mm_xor_si128(
                    phi,
                    _mm_xor_si128(
                        _mm_xor_si128(
                            _mm_shuffle_epi8(lane(th[s][0]), n0),
                            _mm_shuffle_epi8(lane(th[s][1]), n1),
                        ),
                        _mm_xor_si128(
                            _mm_shuffle_epi8(lane(th[s][2]), n2),
                            _mm_shuffle_epi8(lane(th[s][3]), n3),
                        ),
                    ),
                );
            }
            let dp = dst_bytes.add(off) as *mut __m128i;
            let d0 = _mm_loadu_si128(dp);
            let d1 = _mm_loadu_si128(dp.add(1));
            _mm_storeu_si128(dp, _mm_xor_si128(d0, _mm_unpacklo_epi8(plo, phi)));
            _mm_storeu_si128(dp.add(1), _mm_xor_si128(d1, _mm_unpackhi_epi8(plo, phi)));
        }
    }
}

/// [`xor_mul_multi_avx2`]'s SSSE3 form: 128-bit lanes, 32-byte chunks,
/// the same hoisted accumulators. Pre-AVX2 x86 (Core 2 through Ivy
/// Bridge, AMD before Excavator) and any AVX2 part the OS has masked.
#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "ssse3")]
unsafe fn xor_mul_multi_ssse3(dst: &mut [u16], srcs: &[&[u8]], coeffs: &[u16]) -> usize {
    if srcs.is_empty() {
        return 0;
    }
    let usable = srcs.iter().fold(dst.len() * 2, |m, s| m.min(s.len()));
    let chunks = usable / 32;
    if chunks == 0 {
        return 0;
    }
    let mut g0 = 0usize;
    while g0 < srcs.len() {
        let g1 = (g0 + 4).min(srcs.len());
        let s = &srcs[g0..g1];
        let c = &coeffs[g0..g1];
        // SAFETY: ssse3 is enabled on this fn per #[target_feature]
        // (runtime-verified at the dispatch site); `chunks` is clamped to
        // the shortest source and to dst's byte length.
        unsafe {
            match g1 - g0 {
                1 => xor_mul_multi_ssse3_n::<1>(dst, s, c, chunks),
                2 => xor_mul_multi_ssse3_n::<2>(dst, s, c, chunks),
                3 => xor_mul_multi_ssse3_n::<3>(dst, s, c, chunks),
                _ => xor_mul_multi_ssse3_n::<4>(dst, s, c, chunks),
            }
        }
        g0 = g1;
    }
    chunks * 16
}

#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "ssse3")]
unsafe fn xor_mul_multi_ssse3_n<const N: usize>(
    dst: &mut [u16],
    srcs: &[&[u8]],
    coeffs: &[u16],
    chunks: usize,
) {
    use std::arch::x86_64::*;
    debug_assert_eq!(srcs.len(), N);
    debug_assert!(srcs.iter().all(|s| s.len() >= chunks * 32));
    // SAFETY: ssse3 is enabled here per #[target_feature] (runtime-
    // verified at the dispatch site). All pointer accesses stay within
    // the first chunks * 32 bytes of each slice: the caller clamps
    // `chunks` to the shortest source and to dst's byte length.
    unsafe {
        let ld = |t: &[u8; 16]| _mm_loadu_si128(t.as_ptr() as *const __m128i);
        let mut tl = [[_mm_setzero_si128(); 4]; N];
        let mut th = [[_mm_setzero_si128(); 4]; N];
        let mut src_ptr = [std::ptr::null::<u8>(); N];
        for s in 0..N {
            let (nl, nh) = nibble_tables(coeffs[s]);
            for j in 0..4 {
                tl[s][j] = ld(&nl[j]);
                th[s][j] = ld(&nh[j]);
            }
            src_ptr[s] = srcs[s].as_ptr();
        }
        let nib = _mm_set1_epi8(0x0f);
        let lo8 = _mm_set1_epi16(0x00ff);
        let dst_bytes = dst.as_mut_ptr() as *mut u8;
        for ch in 0..chunks {
            let off = ch * 32;
            let mut plo = _mm_setzero_si128();
            let mut phi = _mm_setzero_si128();
            for s in 0..N {
                let sp = src_ptr[s].add(off) as *const __m128i;
                let v0 = _mm_loadu_si128(sp);
                let v1 = _mm_loadu_si128(sp.add(1));
                let slo = _mm_packus_epi16(_mm_and_si128(v0, lo8), _mm_and_si128(v1, lo8));
                let shi = _mm_packus_epi16(_mm_srli_epi16(v0, 8), _mm_srli_epi16(v1, 8));
                let n0 = _mm_and_si128(slo, nib);
                let n1 = _mm_and_si128(_mm_srli_epi16(slo, 4), nib);
                let n2 = _mm_and_si128(shi, nib);
                let n3 = _mm_and_si128(_mm_srli_epi16(shi, 4), nib);
                plo = _mm_xor_si128(
                    plo,
                    _mm_xor_si128(
                        _mm_xor_si128(
                            _mm_shuffle_epi8(tl[s][0], n0),
                            _mm_shuffle_epi8(tl[s][1], n1),
                        ),
                        _mm_xor_si128(
                            _mm_shuffle_epi8(tl[s][2], n2),
                            _mm_shuffle_epi8(tl[s][3], n3),
                        ),
                    ),
                );
                phi = _mm_xor_si128(
                    phi,
                    _mm_xor_si128(
                        _mm_xor_si128(
                            _mm_shuffle_epi8(th[s][0], n0),
                            _mm_shuffle_epi8(th[s][1], n1),
                        ),
                        _mm_xor_si128(
                            _mm_shuffle_epi8(th[s][2], n2),
                            _mm_shuffle_epi8(th[s][3], n3),
                        ),
                    ),
                );
            }
            let dp = dst_bytes.add(off) as *mut __m128i;
            let d0 = _mm_loadu_si128(dp);
            let d1 = _mm_loadu_si128(dp.add(1));
            _mm_storeu_si128(dp, _mm_xor_si128(d0, _mm_unpacklo_epi8(plo, phi)));
            _mm_storeu_si128(dp.add(1), _mm_xor_si128(d1, _mm_unpackhi_epi8(plo, phi)));
        }
    }
}

/// The pmull Karatsuba fold, plain-NEON form (no sha3): same Q-register
/// coefficients and direct `pmull2` high-half multiplies as the sha3
/// kernel, with plain XOR accumulation. NEON (incl. pmull on poly8) is
/// baseline on aarch64.
#[cfg(target_arch = "aarch64")]
unsafe fn xor_mul_multi_neon(dst: &mut [u16], srcs: &[&[u8]], coeffs: &[u16]) -> usize {
    use std::arch::aarch64::*;
    let chunks = (dst.len() * 2) / 32;
    if chunks == 0 || srcs.is_empty() {
        return 0;
    }
    // SAFETY: NEON (incl. pmull on poly8) is baseline on aarch64, no
    // feature check needed (see the doc above). All pointer accesses stay
    // within the first chunks * 32 bytes: in bounds for dst by
    // chunks = (dst.len() * 2) / 32, and for each source by
    // xor_mul_multi_into's documented precondition (debug_asserted there)
    // that every source covers dst's full byte length.
    unsafe {
        let mut c_lo = [vdupq_n_p8(0); 16];
        let mut c_hi = [vdupq_n_p8(0); 16];
        let mut c_mid = [vdupq_n_p8(0); 16];
        let n = srcs.len().min(16);
        for s in 0..n {
            c_lo[s] = vdupq_n_p8(coeffs[s] as u8);
            c_hi[s] = vdupq_n_p8((coeffs[s] >> 8) as u8);
            c_mid[s] = vreinterpretq_p8_u8(veorq_u8(
                vreinterpretq_u8_p8(c_lo[s]),
                vreinterpretq_u8_p8(c_hi[s]),
            ));
        }
        let xr = |a: poly16x8_t, b: uint16x8_t| -> poly16x8_t {
            vreinterpretq_p16_u16(veorq_u16(vreinterpretq_u16_p16(a), b))
        };
        let pml = |d: poly8x16_t, c: poly8x16_t| -> uint16x8_t {
            vreinterpretq_u16_p16(vmull_p8(vget_low_p8(d), vget_low_p8(c)))
        };
        let pmh = |d: poly8x16_t, c: poly8x16_t| -> uint16x8_t {
            vreinterpretq_u16_p16(vmull_high_p8(d, c))
        };
        let dst_bytes = dst.as_mut_ptr() as *mut u8;
        for ch in 0..chunks {
            let off = ch * 32;
            let mut low1 = vdupq_n_p16(0);
            let mut low2 = vdupq_n_p16(0);
            let mut mid1 = vdupq_n_p16(0);
            let mut mid2 = vdupq_n_p16(0);
            let mut high1 = vdupq_n_p16(0);
            let mut high2 = vdupq_n_p16(0);
            for (s, &src) in srcs[..n].iter().enumerate() {
                let d = vld2q_u8(src.as_ptr().add(off));
                let dlo = vreinterpretq_p8_u8(d.0);
                let dhi = vreinterpretq_p8_u8(d.1);
                let dmid = vreinterpretq_p8_u8(veorq_u8(d.0, d.1));
                low1 = xr(low1, pml(dlo, c_lo[s]));
                low2 = xr(low2, pmh(dlo, c_lo[s]));
                mid1 = xr(mid1, pml(dmid, c_mid[s]));
                mid2 = xr(mid2, pmh(dmid, c_mid[s]));
                high1 = xr(high1, pml(dhi, c_hi[s]));
                high2 = xr(high2, pmh(dhi, c_hi[s]));
            }
            let (out_lo, out_hi) = clmul_reduce(low1, low2, mid1, mid2, high1, high2);
            let dp = dst_bytes.add(off);
            let mut vb = vld2q_u8(dp);
            vb.0 = veorq_u8(vb.0, out_lo);
            vb.1 = veorq_u8(vb.1, out_hi);
            vst2q_u8(dp, vb);
        }
    }
    chunks * 16
}

/// The sha3 twin of [`xor_mul_multi_neon`]: sources are folded in PAIRS
/// with EOR3 merging both contributions into an accumulator per op
/// (ParPar 581af3e "Allow EOR3 accumulation in ARM CLMul kernels") -
/// a third of the accumulate XORs disappear. Apple Silicon has sha3.
#[cfg(target_arch = "aarch64")]
#[target_feature(enable = "neon,sha3")]
unsafe fn xor_mul_multi_neon_sha3(dst: &mut [u16], srcs: &[&[u8]], coeffs: &[u16]) -> usize {
    // Monomorphize the full-width case: a compile-time source count lets
    // LLVM fully unroll the inner loop and pin the coefficient array in
    // registers (ParPar generates its kernels per srcCount for the same
    // reason).
    if srcs.len() == 8 {
        // SAFETY: same contract as this fn, forwarded unchanged; neon+sha3
        // are already enabled here per #[target_feature], covering the
        // callee's requirement.
        return unsafe { xor_mul_multi_neon_sha3_n::<8>(dst, srcs, coeffs) };
    }
    // SAFETY: as above.
    unsafe { xor_mul_multi_neon_sha3_n::<0>(dst, srcs, coeffs) }
}

#[cfg(target_arch = "aarch64")]
#[target_feature(enable = "neon,sha3")]
unsafe fn xor_mul_multi_neon_sha3_n<const NC: usize>(
    dst: &mut [u16],
    srcs: &[&[u8]],
    coeffs: &[u16],
) -> usize {
    use std::arch::aarch64::*;
    let chunks = (dst.len() * 2) / 32;
    if chunks == 0 || srcs.is_empty() {
        return 0;
    }
    // SAFETY: neon+sha3 are enabled here per #[target_feature] (runtime-
    // verified by the sha3 detect at the dispatch site). All pointer
    // accesses stay within the first chunks * 32 bytes: in bounds for dst
    // by chunks = (dst.len() * 2) / 32, and for each source by
    // xor_mul_multi_into's documented precondition (debug_asserted there)
    // that every source covers dst's full byte length.
    unsafe {
        // Q-register coefficient splats: the LOW-half multiply reads the
        // D register aliasing the low half (free), and the HIGH half goes
        // through `vmull_high_p8` (pmull2) directly - extracting high
        // halves into D registers costs a real move per multiply, six per
        // source per chunk, and that was measurably the kernel's drag.
        let mut c_lo = [vdupq_n_p8(0); 16];
        let mut c_hi = [vdupq_n_p8(0); 16];
        let mut c_mid = [vdupq_n_p8(0); 16];
        let n = if NC > 0 { NC } else { srcs.len().min(16) };
        for s in 0..n {
            c_lo[s] = vdupq_n_p8(coeffs[s] as u8);
            c_hi[s] = vdupq_n_p8((coeffs[s] >> 8) as u8);
            c_mid[s] = vreinterpretq_p8_u8(veorq_u8(
                vreinterpretq_u8_p8(c_lo[s]),
                vreinterpretq_u8_p8(c_hi[s]),
            ));
        }
        let eor3 = |a: poly16x8_t, b: uint16x8_t, c: uint16x8_t| -> poly16x8_t {
            vreinterpretq_p16_u16(veor3q_u16(vreinterpretq_u16_p16(a), b, c))
        };
        let pml = |d: poly8x16_t, c: poly8x16_t| -> uint16x8_t {
            vreinterpretq_u16_p16(vmull_p8(vget_low_p8(d), vget_low_p8(c)))
        };
        let pmh = |d: poly8x16_t, c: poly8x16_t| -> uint16x8_t {
            vreinterpretq_u16_p16(vmull_high_p8(d, c))
        };
        let dst_bytes = dst.as_mut_ptr() as *mut u8;
        for ch in 0..chunks {
            let off = ch * 32;
            let mut low1 = vdupq_n_p16(0);
            let mut low2 = vdupq_n_p16(0);
            let mut mid1 = vdupq_n_p16(0);
            let mut mid2 = vdupq_n_p16(0);
            let mut high1 = vdupq_n_p16(0);
            let mut high2 = vdupq_n_p16(0);
            let mut s = 0usize;
            while s + 1 < n {
                let da = vld2q_u8(srcs[s].as_ptr().add(off));
                let db = vld2q_u8(srcs[s + 1].as_ptr().add(off));
                let dalo = vreinterpretq_p8_u8(da.0);
                let dahi = vreinterpretq_p8_u8(da.1);
                let damid = vreinterpretq_p8_u8(veorq_u8(da.0, da.1));
                let dblo = vreinterpretq_p8_u8(db.0);
                let dbhi = vreinterpretq_p8_u8(db.1);
                let dbmid = vreinterpretq_p8_u8(veorq_u8(db.0, db.1));
                low1 = eor3(low1, pml(dalo, c_lo[s]), pml(dblo, c_lo[s + 1]));
                low2 = eor3(low2, pmh(dalo, c_lo[s]), pmh(dblo, c_lo[s + 1]));
                mid1 = eor3(mid1, pml(damid, c_mid[s]), pml(dbmid, c_mid[s + 1]));
                mid2 = eor3(mid2, pmh(damid, c_mid[s]), pmh(dbmid, c_mid[s + 1]));
                high1 = eor3(high1, pml(dahi, c_hi[s]), pml(dbhi, c_hi[s + 1]));
                high2 = eor3(high2, pmh(dahi, c_hi[s]), pmh(dbhi, c_hi[s + 1]));
                s += 2;
            }
            if s < n {
                let d = vld2q_u8(srcs[s].as_ptr().add(off));
                let dlo = vreinterpretq_p8_u8(d.0);
                let dhi = vreinterpretq_p8_u8(d.1);
                let dmid = vreinterpretq_p8_u8(veorq_u8(d.0, d.1));
                let xr = |a: poly16x8_t, b: uint16x8_t| -> poly16x8_t {
                    vreinterpretq_p16_u16(veorq_u16(vreinterpretq_u16_p16(a), b))
                };
                low1 = xr(low1, pml(dlo, c_lo[s]));
                low2 = xr(low2, pmh(dlo, c_lo[s]));
                mid1 = xr(mid1, pml(dmid, c_mid[s]));
                mid2 = xr(mid2, pmh(dmid, c_mid[s]));
                high1 = xr(high1, pml(dhi, c_hi[s]));
                high2 = xr(high2, pmh(dhi, c_hi[s]));
            }
            let (out_lo, out_hi) = clmul_reduce(low1, low2, mid1, mid2, high1, high2);
            let dp = dst_bytes.add(off);
            let mut vb = vld2q_u8(dp);
            vb.0 = veorq_u8(vb.0, out_lo);
            vb.1 = veorq_u8(vb.1, out_hi);
            vst2q_u8(dp, vb);
        }
    }
    chunks * 16
}

/// Barrett reduction of the accumulated Karatsuba terms mod 0x1100B,
/// ported from ParPar's `gf16_clmul_neon_reduction` (public domain)
/// including its late-2024 refinements (the 0x18 shift trick and the
/// shortened dependency chains). Returns the reduced product's
/// (low bytes, high bytes) for 16 words.
#[cfg(target_arch = "aarch64")]
#[inline(always)]
unsafe fn clmul_reduce(
    low1: std::arch::aarch64::poly16x8_t,
    low2: std::arch::aarch64::poly16x8_t,
    mid1: std::arch::aarch64::poly16x8_t,
    mid2: std::arch::aarch64::poly16x8_t,
    high1: std::arch::aarch64::poly16x8_t,
    high2: std::arch::aarch64::poly16x8_t,
) -> (
    std::arch::aarch64::uint8x16_t,
    std::arch::aarch64::uint8x16_t,
) {
    use std::arch::aarch64::*;
    // SAFETY: value-only NEON intrinsics, no memory access; NEON is
    // baseline on aarch64, so there is no feature precondition.
    unsafe {
        // Repack the 16-bit pmull lanes into (low byte, high byte)
        // planes across all 16 words.
        let hi = vuzpq_u8(vreinterpretq_u8_p16(high1), vreinterpretq_u8_p16(high2));
        let lo = vuzpq_u8(vreinterpretq_u8_p16(low1), vreinterpretq_u8_p16(low2));
        let mid = vuzpq_u8(vreinterpretq_u8_p16(mid1), vreinterpretq_u8_p16(mid2));
        // Merge the Karatsuba middle term into the low/high planes.
        let libytes = veorq_u8(hi.0, lo.1);
        let l1 = veorq_u8(veorq_u8(libytes, lo.0), mid.0);
        let h0 = veorq_u8(veorq_u8(libytes, hi.1), mid.1);
        let h1 = hi.1;
        // Barrett: first coefficient 0x1111a; multiply (h1:h0) by 0x11110.
        let mut th0 = vsriq_n_u8(vshlq_n_u8(h1, 4), h0, 4);
        let th1 = veorq_u8(h1, vshrq_n_u8(h1, 4));
        th0 = veorq_u8(veorq_u8(th0, th1), h0);
        let th0_hi3 = vshrq_n_u8(th0, 5);
        let th0_hi1 = vshrq_n_u8(th0_hi3, 2);
        // The 0x1a tail: h1 has only 7 significant bits, so 0x18 works
        // and the 0x8 part is a plain shift.
        th0 = veorq_u8(th0, vshrq_n_u8(h1, 5));
        // Multiply the quotient by the polynomial's low bits (0x0b).
        let red_l = vdupq_n_p8(0x0b);
        let new_h1 = vsliq_n_u8(th0_hi3, th0, 4);
        let th1m = vreinterpretq_u8_p8(vmulq_p8(vreinterpretq_p8_u8(th1), red_l));
        let th0m = vreinterpretq_u8_p8(vmulq_p8(vreinterpretq_p8_u8(th0), red_l));
        let out_lo = veorq_u8(lo.0, th0m);
        let out_hi = veorq_u8(veorq_u8(new_h1, th0_hi1), veorq_u8(th1m, l1));
        (out_lo, out_hi)
    }
}

/// View a u16 word slice as its PAR2 wire bytes. PAR2 reads slices as
/// little-endian words, so on the LE targets we ship this is a free
/// cast. (A big-endian port would need a byte-swapping copy instead -
/// hence the cfg, which makes any such port fail loudly at build time.)
#[cfg(target_endian = "little")]
pub fn words_as_bytes(w: &[u16]) -> &[u8] {
    // SAFETY: u16 has no padding or invalid bit patterns, and the cast
    // only narrows alignment.
    unsafe { std::slice::from_raw_parts(w.as_ptr().cast(), w.len() * 2) }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_values() {
        // 2^16 mod the generator polynomial: 0x1100B with bit 16 dropped.
        assert_eq!(pow2(16), 0x100B);
        assert_eq!(pow2(0), 1);
        assert_eq!(pow2(1), 2);
        // Full cycle wraps to 1.
        assert_eq!(pow2(ORDER as u64), 1);
    }

    #[test]
    fn field_axioms_sampled() {
        let xs = [1u16, 2, 3, 0x100B, 0x8000, 0xFFFF, 12345];
        for &a in &xs {
            assert_eq!(mul(a, 1), a);
            assert_eq!(mul(a, 0), 0);
            assert_eq!(mul(a, inv(a)), 1, "a·a⁻¹ = 1 for {a:#x}");
            for &b in &xs {
                assert_eq!(mul(a, b), mul(b, a));
                for &c in &xs {
                    assert_eq!(mul(a, mul(b, c)), mul(mul(a, b), c));
                    // Distributivity over XOR (field addition).
                    assert_eq!(mul(a, b ^ c), mul(a, b) ^ mul(a, c));
                }
            }
        }
    }

    #[test]
    fn mul_table_matches_scalar_mul() {
        for c in [0u16, 1, 2, 0x1234, 0xFFFF] {
            let t = MulTable::new(c);
            for w in [0u16, 1, 0xFF, 0x100, 0xABCD, 0xFFFF] {
                assert_eq!(t.mul(w), mul(c, w), "c={c:#x} w={w:#x}");
            }
        }
    }

    #[test]
    fn xor_mul_words_matches_per_word_mul() {
        let mut state = 0x243F6A8885A308D3u64;
        let mut rng = || {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            state
        };
        for c in [0u16, 1, 2, 0x1234, 0xABCD, 0xFFFF] {
            let t = MulTable::new(c);
            for len in [0usize, 1, 15, 16, 17, 64, 4097] {
                let src: Vec<u16> = (0..len).map(|_| rng() as u16).collect();
                let base: Vec<u16> = (0..len).map(|_| rng() as u16).collect();
                let mut want = base.clone();
                for (d, s) in want.iter_mut().zip(&src) {
                    *d ^= mul(c, *s);
                }
                let mut got = base.clone();
                t.xor_mul_words(&mut got, &src);
                assert_eq!(got, want, "c={c:#x} len={len}");
            }
        }
    }

    #[test]
    fn xor_mul_into_handles_short_and_odd_src() {
        let c = 0x1234u16;
        let t = MulTable::new(c);
        let src = [1u8, 2, 3, 4, 5]; // odd length: last word is 0x0005
        let mut dst = vec![0u16; 4];
        t.xor_mul_into(&mut dst, &src);
        assert_eq!(dst[0], mul(c, u16::from_le_bytes([1, 2])));
        assert_eq!(dst[1], mul(c, u16::from_le_bytes([3, 4])));
        assert_eq!(dst[2], mul(c, 5));
        assert_eq!(dst[3], 0, "beyond src stays untouched (zero pad)");
    }

    /// The multi-source fused kernel must equal per-source table folds
    /// exactly: every group width up to the platform maximum, coefficient
    /// classes incl. 0/1/low-byte-only/high-byte-only, random data, and
    /// a non-zero starting dst so the accumulate is exercised. This is
    /// the differential oracle for the ParPar-style pmull port - a wrong
    /// Barrett reduction silently corrupts every repair.
    #[test]
    #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
    fn nibble_tables_match_mul() {
        // Every nibble position and value, for a spread of coefficients
        // including the ones whose xtime chain crosses the reduction.
        let mut state = 0xC0FFEE1234567890u64;
        let mut coeffs: Vec<u16> = vec![0, 1, 2, 3, 0x8000, 0x8001, 0xFFFF, 0x100B, 0x1234];
        for _ in 0..2000 {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            coeffs.push(state as u16);
        }
        for c in coeffs {
            let (nl, nh) = nibble_tables(c);
            for j in 0..4 {
                for n in 0..16u16 {
                    let p = mul(c, n << (4 * j));
                    assert_eq!(nl[j][n as usize], p as u8, "c={c:04x} j={j} n={n}");
                    assert_eq!(nh[j][n as usize], (p >> 8) as u8, "c={c:04x} j={j} n={n}");
                }
            }
        }
    }

    /// The scheduling granule must be the SELECTED kernel's real
    /// destination chunk, not a guess: a buffer of exactly one granule is
    /// consumed whole, and - where the granule is wider than 16 - half a
    /// granule is consumed by nothing at all. That second half is the
    /// point. `fold_parallel` and `fold_chunk_multi` align their column
    /// units and cache tiles to this number precisely so no unit ends
    /// mid-chunk and falls to the per-source remainder path, so a kernel
    /// that later changes its chunk width must fail here rather than
    /// quietly cost the scheduler a fold table per (row, group, source).
    ///
    /// This pins the SHIPPING geometry, so it reads the unforced
    /// function: `NZBFAST_GF16_GRANULE` deliberately overrides it and
    /// nothing here sets that variable (a `OnceLock` read is per
    /// process, and the one-process suite would carry a forced value
    /// into every later test in the binary).
    #[test]
    fn schedule_granule_is_the_selected_kernels_chunk() {
        let fan_in = multi_fold_width();
        let granule = multi_fold_schedule_granule_words(fan_in);
        assert!(
            granule == 16 || granule == 32,
            "granule {granule} is not one of the two kernel chunk widths"
        );
        assert_eq!(
            granule == 32,
            cfg!(target_arch = "x86_64") && fan_in == 12,
            "only the twelve-source 512-bit GFNI arm consumes 32 words \
             (fan_in={fan_in}, arch x86_64={})",
            cfg!(target_arch = "x86_64")
        );
        // A box only ever dispatches to its BEST kernel, so the checks
        // above see exactly one arm - and that is how the AVX2 nibble
        // arm shipped scheduled at 16 words while consuming 64 bytes
        // (3 Sep 2026, red on the 4-vCPU x86-64 CI runner). It is
        // unreachable by dispatch on both parts the granule was
        // developed on: aarch64 folds 32-byte chunks and a Zen 4 with
        // AVX-512 GFNI takes the 512-bit arm. So pin EVERY arm this CPU
        // can run against the granule its row of the table claims, not
        // just the selected one - the arm a future GFNI-everywhere fleet
        // stops dispatching to is exactly the arm that rots.
        #[cfg(target_arch = "x86_64")]
        {
            // 64 bytes covers the widest arm's granule; each probe reads
            // only the first `want * 2`.
            let wide: Vec<u8> = (0..64).map(|i| i as u8).collect();
            let srcs = [wide.as_slice()];
            let whole = |want: usize, got: usize, arm: &str| {
                assert_eq!(
                    got, want,
                    "{arm} must consume its {want}-word granule whole"
                );
            };
            if is_x86_feature_detected!("avx2") {
                let mut dst = vec![0u16; 16];
                // SAFETY: AVX2 verified by the detect; the source covers
                // dst's full byte length.
                let got = unsafe { xor_mul_multi_avx2(&mut dst, &srcs, &[0x1234]) };
                whole(16, got, "the AVX2 nibble kernel");
            }
            if is_x86_feature_detected!("ssse3") {
                let mut dst = vec![0u16; 16];
                // SAFETY: SSSE3 verified by the detect; source as above.
                let got = unsafe { xor_mul_multi_ssse3(&mut dst, &srcs, &[0x1234]) };
                whole(16, got, "the SSSE3 nibble kernel");
            }
            if is_x86_feature_detected!("gfni") && is_x86_feature_detected!("avx2") {
                let mut dst = vec![0u16; 16];
                // SAFETY: GFNI and AVX2 verified by the detect; source as
                // above.
                let got = unsafe { xor_mul_multi_gfni(&mut dst, &srcs, &[0x1234]) };
                whole(16, got, "the GFNI affine2x kernel");
            }
            if is_x86_feature_detected!("avx512f")
                && is_x86_feature_detected!("avx512bw")
                && is_x86_feature_detected!("gfni")
            {
                let mut dst = vec![0u16; 32];
                // SAFETY: the three features verified by the detects;
                // source as above.
                let got = unsafe { xor_mul_multi_gfni512(&mut dst, &srcs, &[0x1234]) };
                whole(32, got, "the 512-bit GFNI kernel");
            }
        }
        #[cfg(target_arch = "aarch64")]
        {
            let wide: Vec<u8> = (0..32).map(|i| i as u8).collect();
            let srcs = [wide.as_slice()];
            let mut dst = vec![0u16; 16];
            // SAFETY: plain NEON is baseline on aarch64; the source
            // covers dst's full byte length.
            let got = unsafe { xor_mul_multi_neon(&mut dst, &srcs, &[0x1234]) };
            assert_eq!(
                got, 16,
                "the NEON PMULL kernel must consume its granule whole"
            );
            if std::arch::is_aarch64_feature_detected!("sha3") {
                let mut dst = vec![0u16; 16];
                // SAFETY: sha3 verified by the detect; source as above.
                let got = unsafe { xor_mul_multi_neon_sha3(&mut dst, &srcs, &[0x1234]) };
                assert_eq!(
                    got, 16,
                    "the NEON sha3 kernel must consume its granule whole"
                );
            }
        }
        if fan_in == 0 {
            return; // no fused kernel selected; the table path schedules
        }
        let src: Vec<u8> = (0..granule * 2).map(|i| i as u8).collect();
        let srcs = [src.as_slice()];
        let mut dst = vec![0u16; granule];
        assert_eq!(
            xor_mul_multi_into(&mut dst, &srcs, &[0x1234]),
            granule,
            "one granule must be consumed whole, or every aligned unit \
             still ends mid-chunk"
        );
        if granule > 16 {
            let mut half = vec![0u16; granule / 2];
            assert_eq!(
                xor_mul_multi_into(&mut half, &srcs, &[0x1234]),
                0,
                "half a granule must reach no kernel chunk, or the \
                 granule is wider than the kernel actually needs"
            );
        }
    }

    #[test]
    fn xor_mul_multi_matches_single_source_folds() {
        let width = multi_fold_width();
        if width == 0 {
            return; // no multi kernel on this arch (yet)
        }
        let mut state = 0x0123456789ABCDEFu64;
        let mut rng = || {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            state
        };
        let coeff_pool = [
            0u16, 1, 2, 0x00FF, 0xFF00, 0x0101, 0x100B, 0x8000, 0xFFFF, 0x1234, 0xABCD,
        ];
        // `width + 2` deliberately overshoots the group width: callers
        // never do, but the kernels accept it (the x86 affine2x kernel
        // splits internally into register-resident groups; the aarch64
        // kernels loop sources), and the split path must stay correct.
        for n in 1..=width + 2 {
            for words in [16usize, 17, 32, 48, 160, 4096, 4097] {
                let srcs_owned: Vec<Vec<u8>> = (0..n)
                    .map(|_| (0..words * 2).map(|_| rng() as u8).collect())
                    .collect();
                let srcs: Vec<&[u8]> = srcs_owned.iter().map(|v| v.as_slice()).collect();
                let coeffs: Vec<u16> = (0..n)
                    .map(|i| coeff_pool[(rng() as usize + i) % coeff_pool.len()])
                    .collect();
                let base: Vec<u16> = (0..words).map(|_| rng() as u16).collect();
                let mut want = base.clone();
                for (s, c) in srcs.iter().zip(&coeffs) {
                    MulTable::new(*c).xor_mul_into(&mut want, s);
                }
                let mut got = base.clone();
                let done = xor_mul_multi_into(&mut got, &srcs, &coeffs);
                // Kernels work in whole chunks (16 words on aarch64, 32
                // on x86); whatever they leave is finished per-source.
                assert!(
                    done <= words && done.is_multiple_of(16),
                    "chunk accounting n={n} words={words} done={done}"
                );
                for (s, c) in srcs.iter().zip(&coeffs) {
                    MulTable::new(*c).xor_mul_into(&mut got[done..], &s[done * 2..]);
                }
                assert_eq!(got, want, "n={n} words={words} coeffs={coeffs:x?}");
                // All-one is a dedicated direct-XOR SIMD kernel (the
                // exponent-0 repair row). Pin it for every source
                // count and chunk boundary rather than relying on the
                // random coefficient pool to happen to select it.
                let ones = vec![1u16; n];
                let mut want_ones = base.clone();
                for src in &srcs {
                    MulTable::new(1).xor_mul_into(&mut want_ones, src);
                }
                let mut got_ones = base.clone();
                let done = xor_mul_multi_into(&mut got_ones, &srcs, &ones);
                for src in &srcs {
                    MulTable::new(1).xor_mul_into(&mut got_ones[done..], &src[done * 2..]);
                }
                assert_eq!(got_ones, want_ones, "all-one n={n} words={words}");
                // Drive BOTH aarch64 kernels directly - runtime dispatch
                // only ever exercises the best one this CPU has.
                #[cfg(target_arch = "aarch64")]
                {
                    let mut got = base.clone();
                    // SAFETY: plain NEON is baseline on aarch64; every src
                    // holds words * 2 bytes, covering dst's byte length.
                    let done = unsafe { xor_mul_multi_neon(&mut got, &srcs, &coeffs) };
                    for (s, c) in srcs.iter().zip(&coeffs) {
                        MulTable::new(*c).xor_mul_into(&mut got[done..], &s[done * 2..]);
                    }
                    assert_eq!(got, want, "plain-neon n={n} words={words}");
                    if std::arch::is_aarch64_feature_detected!("sha3") {
                        let mut got = base.clone();
                        // SAFETY: sha3 verified by the detect above;
                        // source coverage as above.
                        let done = unsafe { xor_mul_multi_neon_sha3(&mut got, &srcs, &coeffs) };
                        for (s, c) in srcs.iter().zip(&coeffs) {
                            MulTable::new(*c).xor_mul_into(&mut got[done..], &s[done * 2..]);
                        }
                        assert_eq!(got, want, "sha3 n={n} words={words}");
                    }
                }
                // Same forcing for the x86 GFNI multi kernel (dispatch
                // covers it only on gfni+avx2 hardware, which is also
                // the only place it can run - but force it so the test
                // name pins WHICH kernel failed).
                #[cfg(target_arch = "x86_64")]
                if is_x86_feature_detected!("gfni") && is_x86_feature_detected!("avx2") {
                    let mut got = base.clone();
                    // SAFETY: GFNI and AVX2 verified by the detect above;
                    // the kernel clamps to the shortest source.
                    let done = unsafe { xor_mul_multi_gfni(&mut got, &srcs, &coeffs) };
                    for (s, c) in srcs.iter().zip(&coeffs) {
                        MulTable::new(*c).xor_mul_into(&mut got[done..], &s[done * 2..]);
                    }
                    assert_eq!(got, want, "gfni-multi n={n} words={words}");
                }
                #[cfg(target_arch = "x86_64")]
                if is_x86_feature_detected!("avx512f")
                    && is_x86_feature_detected!("avx512bw")
                    && is_x86_feature_detected!("gfni")
                {
                    let mut got = base.clone();
                    // SAFETY: the three features verified by the detects
                    // above; the kernel clamps to the shortest source.
                    let done = unsafe { xor_mul_multi_gfni512(&mut got, &srcs, &coeffs) };
                    assert!(
                        done.is_multiple_of(16),
                        "gfni512 chunk accounting done={done}"
                    );
                    for (s, c) in srcs.iter().zip(&coeffs) {
                        MulTable::new(*c).xor_mul_into(&mut got[done..], &s[done * 2..]);
                    }
                    assert_eq!(got, want, "gfni512-multi n={n} words={words}");
                }
                // And the two shuffle kernels, which dispatch never picks
                // on a GFNI box but which every other x86 runs.
                #[cfg(target_arch = "x86_64")]
                if is_x86_feature_detected!("avx2") {
                    let mut got = base.clone();
                    // SAFETY: AVX2 verified by the detect above; the
                    // kernel clamps to the shortest source.
                    let done = unsafe { xor_mul_multi_avx2(&mut got, &srcs, &coeffs) };
                    assert!(done.is_multiple_of(16), "avx2 chunk accounting done={done}");
                    for (s, c) in srcs.iter().zip(&coeffs) {
                        MulTable::new(*c).xor_mul_into(&mut got[done..], &s[done * 2..]);
                    }
                    assert_eq!(got, want, "avx2-multi n={n} words={words}");
                }
                #[cfg(target_arch = "x86_64")]
                if is_x86_feature_detected!("ssse3") {
                    let mut got = base.clone();
                    // SAFETY: SSSE3 verified by the detect above; same clamp.
                    let done = unsafe { xor_mul_multi_ssse3(&mut got, &srcs, &coeffs) };
                    assert!(
                        done.is_multiple_of(16),
                        "ssse3 chunk accounting done={done}"
                    );
                    for (s, c) in srcs.iter().zip(&coeffs) {
                        MulTable::new(*c).xor_mul_into(&mut got[done..], &s[done * 2..]);
                    }
                    assert_eq!(got, want, "ssse3-multi n={n} words={words}");
                }
            }
        }
    }

    /// The uneven-source fixture the two clamp tests below share: a 47-byte
    /// source beside a 96-byte one, so only ONE 32-byte chunk is legal and a
    /// kernel that clamped to the LONGEST source would read out of bounds.
    /// Returns (sources, starting dst, the scalar oracle's answer).
    #[cfg(any(target_arch = "aarch64", target_arch = "x86_64"))]
    fn xor_multi_clamp_fixture() -> (Vec<Vec<u8>>, Vec<u16>, Vec<u16>) {
        let srcs = vec![vec![0x5a; 47], vec![0xa5; 96]];
        let base: Vec<u16> = (0..64).map(|i| i as u16 * 257).collect();
        let mut want = base.clone();
        for src in &srcs {
            MulTable::new(1).xor_mul_into(&mut want[..16], &src[..32]);
        }
        (srcs, base, want)
    }

    /// Each direct-XOR kernel gets its own test rather than one test with
    /// per-arch arms inside it: a reference under a STATEMENT `#[cfg]` does
    /// not carry that cfg to a reader (`cfg-symbol-gate` reads the enclosing
    /// item's), so the kernel and the only thing that names it share one
    /// `#[cfg]` line here.
    #[test]
    #[cfg(target_arch = "aarch64")]
    fn xor_multi_neon_clamps_to_shortest_source() {
        let (srcs, mut got, want) = xor_multi_clamp_fixture();
        let refs: Vec<&[u8]> = srcs.iter().map(Vec::as_slice).collect();
        // SAFETY: NEON is baseline on aarch64; the intentionally uneven
        // source lengths exercise the kernel's shortest-source clamp.
        let done = unsafe { xor_multi_neon(&mut got, &refs) };
        assert_eq!(done, 16);
        assert_eq!(got, want);
    }

    #[test]
    #[cfg(target_arch = "x86_64")]
    fn xor_multi_x86_clamps_to_shortest_source() {
        let (srcs, base, want) = xor_multi_clamp_fixture();
        let refs: Vec<&[u8]> = srcs.iter().map(Vec::as_slice).collect();
        // Both x86 kernels are driven directly - runtime dispatch only ever
        // exercises the best one this CPU has, which would leave the SSE2
        // fallback untested on every box in the fleet.
        let mut got = base.clone();
        // SAFETY: SSE2 is baseline on x86_64; uneven source lengths
        // exercise the shortest-source clamp.
        let done = unsafe { xor_multi_sse2(&mut got, &refs) };
        assert_eq!(done, 16);
        assert_eq!(got, want);
        if is_x86_feature_detected!("avx2") {
            let mut got = base;
            // SAFETY: AVX2 verified by the detect above; same clamp.
            let done = unsafe { xor_multi_avx2(&mut got, &refs) };
            assert_eq!(done, 16);
            assert_eq!(got, want);
        }
    }

    /// `xor_mul_into` must match a straight per-word GF multiply for every
    /// length across, and just past, the NEON 32-byte chunk boundary and
    /// odd tails - on aarch64 this is the NEON path vs a scalar oracle,
    /// with a non-zero starting `dst` so the accumulate (`^=`) is exercised.
    #[test]
    fn xor_mul_into_matches_scalar_all_lengths() {
        let mut state = 0x9E3779B97F4A7C15u64;
        let mut rng = || {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            state
        };
        for c in [0u16, 1, 2, 0x00FF, 0x0101, 0x1234, 0xABCD, 0xFFFF] {
            let t = MulTable::new(c);
            for len in [0usize, 1, 2, 3, 15, 16, 31, 32, 33, 64, 65, 127, 4096, 4097] {
                let src: Vec<u8> = (0..len).map(|_| rng() as u8).collect();
                let words = len.div_ceil(2);
                let base: Vec<u16> = (0..words + 3).map(|_| rng() as u16).collect();
                // Oracle: start from `base`, add c·word per src word.
                let mut want = base.clone();
                for (i, s) in src.chunks(2).enumerate() {
                    let w = if s.len() == 2 {
                        u16::from_le_bytes([s[0], s[1]])
                    } else {
                        s[0] as u16
                    };
                    want[i] ^= mul(c, w);
                }
                let mut got = base.clone();
                t.xor_mul_into(&mut got, &src);
                assert_eq!(got, want, "c={c:#x} len={len}");

                // On x86_64 also drive each kernel directly - runtime
                // dispatch would only ever exercise the best one the CPU
                // has (e.g. AVX2 shadowing SSSE3).
                #[cfg(target_arch = "x86_64")]
                {
                    if is_x86_feature_detected!("ssse3") {
                        let mut got = base.clone();
                        // SAFETY: SSSE3 verified by the detect above; got
                        // holds words + 3 elements, a word for every byte
                        // pair of src.
                        let done = unsafe { fold_ssse3(&t.nl, &t.nh, &mut got, &src) };
                        MulTable::xor_mul_scalar(&t.lo, &t.hi, &mut got[done..], &src[done * 2..]);
                        assert_eq!(got, want, "ssse3 c={c:#x} len={len}");
                    }
                    if is_x86_feature_detected!("avx2") {
                        let mut got = base.clone();
                        // SAFETY: AVX2 verified by the detect above; got
                        // covers src as above.
                        let done = unsafe { fold_avx2(&t.nl, &t.nh, &mut got, &src) };
                        MulTable::xor_mul_scalar(&t.lo, &t.hi, &mut got[done..], &src[done * 2..]);
                        assert_eq!(got, want, "avx2 c={c:#x} len={len}");
                    }
                    if is_x86_feature_detected!("gfni") && is_x86_feature_detected!("avx2") {
                        let mut got = base.clone();
                        // SAFETY: GFNI and AVX2 verified by the detect
                        // above; got covers src as above.
                        let done = unsafe { fold_gfni(&t.affine, &mut got, &src) };
                        MulTable::xor_mul_scalar(&t.lo, &t.hi, &mut got[done..], &src[done * 2..]);
                        assert_eq!(got, want, "gfni c={c:#x} len={len}");
                    }
                }
            }
        }
    }

    /// [`FoldTable`] must match the same per-word oracle as
    /// [`MulTable::xor_mul_into`] at every length class - in particular
    /// the sub-chunk tails and the odd trailing byte, which exercise
    /// the nibble-table scalar path the compact table falls back on.
    #[test]
    fn fold_table_matches_scalar_all_lengths() {
        let mut state = 0xD1B54A32D192ED03u64;
        let mut rng = || {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            state
        };
        for c in [0u16, 1, 2, 0x00FF, 0x0101, 0x1234, 0xABCD, 0xFFFF] {
            let t = FoldTable::new(c);
            for len in [0usize, 1, 2, 3, 15, 16, 31, 32, 33, 64, 65, 127, 4096, 4097] {
                let src: Vec<u8> = (0..len).map(|_| rng() as u8).collect();
                let words = len.div_ceil(2);
                let base: Vec<u16> = (0..words + 3).map(|_| rng() as u16).collect();
                let mut want = base.clone();
                for (i, s) in src.chunks(2).enumerate() {
                    let w = if s.len() == 2 {
                        u16::from_le_bytes([s[0], s[1]])
                    } else {
                        s[0] as u16
                    };
                    want[i] ^= mul(c, w);
                }
                let mut got = base.clone();
                t.xor_mul_into(&mut got, &src);
                assert_eq!(got, want, "fold-table c={c:#x} len={len}");
            }
        }
    }
}
